/*
About pages for the page builder (generated). Insert-only: a page that already exists is never overwritten,
so edits made in the admin site are kept. English holds the blocks; other languages hold translated text by id.
*/
SET NOCOUNT ON;

IF NOT EXISTS (SELECT 1 FROM [site].[Page] WHERE [Slug] = 'about')
BEGIN
    INSERT [site].[Page] ([Slug], [IsPublished]) VALUES ('about', 1);
    DECLARE @p_about INT = SCOPE_IDENTITY();
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_about, 'en', N'About Us | Selfie with Parent', N'Selfie with Parent turns a simple photo into a thank-you to the people who raised us, and that thank-you into care for elders.', N'[{"type":"hero","eyebrow":"About us","title":"A thank-you,","highlight":"one selfie at a time","lead":"Selfie with Parent is a people''s campaign that turns a simple photo into a moment of gratitude, and that gratitude into care for the elders around us.","id":"b104"},{"type":"tabs","items":[{"id":"t100","icon":"bi-heart","label":"About us","url":"/about"},{"id":"t101","icon":"bi-person","label":"Our founder","url":"/founder"},{"id":"t102","icon":"bi-signpost-split","label":"Our journey","url":"/journey"},{"id":"t103","icon":"bi-hand-thumbs-up","label":"What we do","url":"/what-we-do"}],"id":"b105"},{"type":"text","kicker":"Who we are","heading":"We help families say what often goes unsaid.","paragraphs":[{"id":"p1","text":"Most of us thank our parents far less often than we mean to. Selfie with Parent makes it easy: take a photo together, add one line about what they taught you, and share it."},{"id":"p2","text":"Every selfie becomes a small, public promise to stay close, and a reminder to look out for elders who have no one to take a picture with."}],"facts":[{"id":"f3","icon":"bi-gift","text":"Free for every family"},{"id":"f4","icon":"bi-translate","text":"Available in six languages"},{"id":"f5","icon":"bi-people","text":"Parents, grandparents and guardians all count"},{"id":"f6","icon":"bi-shield-lock","text":"Your photos, your choice — always with consent"}],"id":"b106"},{"type":"cards","layout":"bento","background":"soft","items":[{"id":"c7","icon":"bi-compass","title":"Our mission","text":"Make thanking our parents and grandparents a habit, not a once-a-year message.","style":"dark","width":5},{"id":"c8","icon":"bi-eye","title":"Our vision","text":"A world where no elder feels forgotten, whether they live with family, alone, or far away.","style":"gold","width":7},{"id":"c9","icon":"bi-patch-check","title":"Our promise to you","text":"Every photo is shared only with the consent of the people in it, kept safe, and taken down whenever you ask.","style":"plain","width":12}],"id":"b107"},{"type":"cards","layout":"grid","columns":4,"kicker":"What we stand for","heading":"Four values behind every selfie","items":[{"id":"c10","icon":"bi-heart","title":"Gratitude first","text":"We celebrate the people who raised us, not likes or followers."},{"id":"c11","icon":"bi-person-check","title":"Consent and dignity","text":"No one appears on our site without agreeing to it, least of all an elder."},{"id":"c12","icon":"bi-house-heart","title":"Every family counts","text":"Single parents, adoptive parents, grandparents raising grandchildren — every family is welcome."},{"id":"c13","icon":"bi-arrow-repeat","title":"Small acts, often","text":"A weekly call does more than a grand gesture once a year."}],"id":"b108"},{"type":"steps","style":"numbered","background":"soft","kicker":"How it works","heading":"Three steps, two minutes","items":[{"id":"s14","title":"Take a selfie together","text":"At home, on a video call, or with an old photo if they are no longer with you."},{"id":"s15","title":"Add one line of thanks","text":"Tell the world one thing they taught you, in any of our six languages."},{"id":"s16","title":"Share it and keep the promise","text":"Post it on our wall, send it to family, and pick one small promise for the week."}],"buttons":[{"id":"b17","label":"Share your selfie","url":"/upload","icon":"bi-camera","style":"primary"}],"id":"b109"},{"type":"cards","layout":"links","columns":3,"kicker":"Get to know us","heading":"The people, the path and the work","items":[{"id":"c18","icon":"bi-person","title":"Meet our founder","text":"Why one person decided a selfie could change how we treat our parents.","url":"/founder","linkLabel":"Read their story"},{"id":"c19","icon":"bi-signpost-split","title":"Our journey","text":"From the first photo to a campaign across towns, villages and schools.","url":"/journey","linkLabel":"See the milestones"},{"id":"c20","icon":"bi-hand-thumbs-up","title":"What we do","text":"Health camps, school programmes, digital help and visits to elders who live alone.","url":"/what-we-do","linkLabel":"Explore our work"}],"id":"b110"},{"type":"faq","background":"soft","kicker":"Good to know","heading":"Questions people ask us","items":[{"id":"q21","question":"Does it cost anything to take part?","answer":"No. Sharing a selfie, taking the pledge and joining our activities is free."},{"id":"q22","question":"Who can share a selfie?","answer":"Anyone with a parent, grandparent or guardian they want to thank. Children under 18 share through a parent or guardian."},{"id":"q23","question":"What happens to my photo?","answer":"It is checked by our team before it appears, shown only where you allow it, and removed whenever you ask."},{"id":"q24","question":"Is the campaign linked to a government scheme?","answer":"Selfie with Parent is an independent campaign. [Add any official partnerships here only once they are confirmed.]"}],"id":"b111"},{"type":"cta","title":"Your turn to say thank you","text":"It takes two minutes, and it might be the photo they keep on their phone for years.","buttons":[{"id":"b25","label":"Share a selfie","url":"/upload","icon":"bi-camera","style":"primary"},{"id":"b26","label":"Get involved","url":"/what-we-do#get-involved","icon":"bi-people","style":"secondary"}],"id":"b112"}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_about, 'hi', N'हमारे बारे में | सेल्फी विद पैरेंट', N'सेल्फी विद पैरेंट एक साधारण फ़ोटो को हमें पालने वालों के लिए धन्यवाद में, और उस धन्यवाद को बुज़ुर्गों की देखभाल में बदल देता है।', N'[{"id":"b104","eyebrow":"हमारे बारे में","title":"एक धन्यवाद,","highlight":"एक-एक सेल्फी के साथ","lead":"सेल्फी विद पैरेंट लोगों का अभियान है जो एक साधारण फ़ोटो को आभार के पल में, और उस आभार को हमारे आसपास के बुज़ुर्गों की देखभाल में बदल देता है।"},{"id":"b105","items":[{"id":"t100","label":"हमारे बारे में"},{"id":"t101","label":"हमारे संस्थापक"},{"id":"t102","label":"हमारा सफ़र"},{"id":"t103","label":"हम क्या करते हैं"}]},{"id":"b106","kicker":"हम कौन हैं","heading":"हम परिवारों को वह कहने में मदद करते हैं जो अक्सर अनकहा रह जाता है।","paragraphs":[{"id":"p1","text":"हम में से ज़्यादातर लोग अपने माता-पिता को जितना चाहते हैं उससे बहुत कम धन्यवाद कहते हैं। सेल्फी विद पैरेंट इसे आसान बनाता है: साथ में एक फ़ोटो लें, उन्होंने आपको जो सिखाया उसके बारे में एक पंक्ति लिखें, और साझा करें।"},{"id":"p2","text":"हर सेल्फी साथ रहने का एक छोटा, सार्वजनिक वादा बन जाती है, और उन बुज़ुर्गों का ध्यान रखने की याद दिलाती है जिनके साथ फ़ोटो लेने वाला कोई नहीं है।"}],"facts":[{"id":"f3","text":"हर परिवार के लिए निःशुल्क"},{"id":"f4","text":"छह भाषाओं में उपलब्ध"},{"id":"f5","text":"माता-पिता, दादा-दादी, नाना-नानी और अभिभावक — सब शामिल हैं"},{"id":"f6","text":"आपकी फ़ोटो, आपकी पसंद — हमेशा सहमति के साथ"}]},{"id":"b107","items":[{"id":"c7","title":"हमारा मिशन","text":"माता-पिता और दादा-दादी को धन्यवाद कहना साल में एक बार का संदेश नहीं, एक आदत बनाना।"},{"id":"c8","title":"हमारी सोच","text":"एक ऐसी दुनिया जहाँ कोई बुज़ुर्ग ख़ुद को भूला हुआ महसूस न करे — चाहे वे परिवार के साथ रहें, अकेले रहें या दूर।"},{"id":"c9","title":"आपसे हमारा वादा","text":"हर फ़ोटो उसमें दिखने वाले लोगों की सहमति से ही साझा होती है, सुरक्षित रखी जाती है, और आपके कहने पर कभी भी हटा दी जाती है।"}]},{"id":"b108","kicker":"हम किसके लिए खड़े हैं","heading":"हर सेल्फी के पीछे चार मूल्य","items":[{"id":"c10","title":"पहले आभार","text":"हम उन लोगों का सम्मान करते हैं जिन्होंने हमें पाला, लाइक्स या फ़ॉलोअर्स का नहीं।"},{"id":"c11","title":"सहमति और सम्मान","text":"कोई भी हमारी साइट पर बिना सहमति के नहीं दिखता, ख़ासकर कोई बुज़ुर्ग।"},{"id":"c12","title":"हर परिवार मायने रखता है","text":"अकेले माता-पिता, गोद लेने वाले माता-पिता, पोते-पोतियों को पालने वाले दादा-दादी — हर परिवार का स्वागत है।"},{"id":"c13","title":"छोटे काम, बार-बार","text":"हर हफ़्ते का एक फ़ोन साल में एक बार के बड़े काम से ज़्यादा असर करता है।"}]},{"id":"b109","kicker":"यह कैसे काम करता है","heading":"तीन कदम, दो मिनट","items":[{"id":"s14","title":"साथ में सेल्फी लें","text":"घर पर, वीडियो कॉल पर, या पुरानी फ़ोटो के साथ अगर वे अब आपके साथ नहीं हैं।"},{"id":"s15","title":"धन्यवाद की एक पंक्ति जोड़ें","text":"दुनिया को बताएं कि उन्होंने आपको क्या सिखाया, हमारी छह भाषाओं में से किसी में भी।"},{"id":"s16","title":"साझा करें और वादा निभाएं","text":"इसे हमारी वॉल पर पोस्ट करें, परिवार को भेजें, और हफ़्ते के लिए एक छोटा वादा चुनें।"}],"buttons":[{"id":"b17","label":"अपनी सेल्फी साझा करें"}]},{"id":"b110","kicker":"हमें जानें","heading":"लोग, रास्ता और काम","items":[{"id":"c18","title":"हमारे संस्थापक से मिलें","text":"एक व्यक्ति ने क्यों सोचा कि एक सेल्फी माता-पिता के प्रति हमारा व्यवहार बदल सकती है।","linkLabel":"उनकी कहानी पढ़ें"},{"id":"c19","title":"हमारा सफ़र","text":"पहली फ़ोटो से लेकर शहरों, गाँवों और स्कूलों तक फैले अभियान तक।","linkLabel":"पड़ाव देखें"},{"id":"c20","title":"हम क्या करते हैं","text":"स्वास्थ्य शिविर, स्कूल कार्यक्रम, डिजिटल मदद और अकेले रहने वाले बुज़ुर्गों से मुलाक़ात।","linkLabel":"हमारा काम देखें"}]},{"id":"b111","kicker":"जानने योग्य","heading":"लोग हमसे क्या पूछते हैं","items":[{"id":"q21","question":"क्या भाग लेने का कोई शुल्क है?","answer":"नहीं। सेल्फी साझा करना, संकल्प लेना और हमारी गतिविधियों में शामिल होना निःशुल्क है।"},{"id":"q22","question":"सेल्फी कौन साझा कर सकता है?","answer":"कोई भी जो अपने माता-पिता, दादा-दादी या अभिभावक को धन्यवाद कहना चाहता है। 18 वर्ष से कम के बच्चे माता-पिता या अभिभावक के ज़रिए साझा करते हैं।"},{"id":"q23","question":"मेरी फ़ोटो का क्या होता है?","answer":"दिखने से पहले हमारी टीम इसकी जाँच करती है, यह वहीं दिखाई जाती है जहाँ आप अनुमति दें, और आपके कहने पर कभी भी हटा दी जाती है।"},{"id":"q24","question":"क्या यह अभियान किसी सरकारी योजना से जुड़ा है?","answer":"सेल्फी विद पैरेंट एक स्वतंत्र अभियान है। [Add any official partnerships here only once they are confirmed.]"}]},{"id":"b112","title":"अब आपकी बारी है धन्यवाद कहने की","text":"इसमें दो मिनट लगते हैं, और शायद यही वह फ़ोटो हो जिसे वे सालों तक अपने फ़ोन में रखें।","buttons":[{"id":"b25","label":"सेल्फी साझा करें"},{"id":"b26","label":"जुड़ें"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_about, 'bn', N'আমাদের সম্পর্কে | সেলফি উইথ প্যারেন্ট', N'সেলফি উইথ প্যারেন্ট একটি সাধারণ ছবিকে আমাদের যাঁরা বড় করেছেন তাঁদের প্রতি ধন্যবাদে, আর সেই ধন্যবাদকে প্রবীণদের যত্নে বদলে দেয়।', N'[{"id":"b104","eyebrow":"আমাদের সম্পর্কে","title":"একটি ধন্যবাদ,","highlight":"একটি করে সেলফিতে","lead":"সেলফি উইথ প্যারেন্ট মানুষের একটি অভিযান, যা একটি সাধারণ ছবিকে কৃতজ্ঞতার মুহূর্তে, আর সেই কৃতজ্ঞতাকে আশপাশের প্রবীণদের যত্নে বদলে দেয়।"},{"id":"b105","items":[{"id":"t100","label":"আমাদের সম্পর্কে"},{"id":"t101","label":"আমাদের প্রতিষ্ঠাতা"},{"id":"t102","label":"আমাদের যাত্রা"},{"id":"t103","label":"আমরা কী করি"}]},{"id":"b106","kicker":"আমরা কারা","heading":"পরিবারগুলো যা প্রায়ই বলতে পারে না, আমরা তা বলতে সাহায্য করি।","paragraphs":[{"id":"p1","text":"আমরা বেশিরভাগই বাবা-মাকে যতটা চাই তার চেয়ে অনেক কম ধন্যবাদ দিই। সেলফি উইথ প্যারেন্ট এটা সহজ করে: একসঙ্গে একটি ছবি তুলুন, তাঁরা আপনাকে যা শিখিয়েছেন তা নিয়ে এক লাইন লিখুন, আর শেয়ার করুন।"},{"id":"p2","text":"প্রতিটি সেলফি কাছে থাকার একটি ছোট, প্রকাশ্য প্রতিশ্রুতি হয়ে ওঠে, আর মনে করিয়ে দেয় সেই প্রবীণদের কথা যাঁদের সঙ্গে ছবি তোলার কেউ নেই।"}],"facts":[{"id":"f3","text":"প্রতিটি পরিবারের জন্য বিনামূল্যে"},{"id":"f4","text":"ছয়টি ভাষায় উপলব্ধ"},{"id":"f5","text":"বাবা-মা, দাদু-দিদা ও অভিভাবক — সবাই গণ্য"},{"id":"f6","text":"আপনার ছবি, আপনার সিদ্ধান্ত — সবসময় সম্মতি নিয়ে"}]},{"id":"b107","items":[{"id":"c7","title":"আমাদের লক্ষ্য","text":"বাবা-মা ও দাদু-দিদাকে ধন্যবাদ জানানোকে বছরে একবারের বার্তা নয়, একটি অভ্যাসে পরিণত করা।"},{"id":"c8","title":"আমাদের স্বপ্ন","text":"এমন এক পৃথিবী যেখানে কোনো প্রবীণ নিজেকে বিস্মৃত মনে করেন না — তাঁরা পরিবারের সঙ্গে থাকুন, একা থাকুন বা দূরে।"},{"id":"c9","title":"আপনার প্রতি আমাদের প্রতিশ্রুতি","text":"প্রতিটি ছবি শুধু ছবির মানুষদের সম্মতিতেই শেয়ার হয়, নিরাপদে রাখা হয়, আর আপনি চাইলে যেকোনো সময় সরিয়ে দেওয়া হয়।"}]},{"id":"b108","kicker":"আমরা কীসের পক্ষে","heading":"প্রতিটি সেলফির পেছনে চারটি মূল্যবোধ","items":[{"id":"c10","title":"কৃতজ্ঞতা আগে","text":"আমরা উদযাপন করি তাঁদের যাঁরা আমাদের বড় করেছেন, লাইক বা ফলোয়ার নয়।"},{"id":"c11","title":"সম্মতি ও মর্যাদা","text":"সম্মতি ছাড়া কেউ আমাদের সাইটে আসেন না, বিশেষ করে কোনো প্রবীণ।"},{"id":"c12","title":"প্রতিটি পরিবার গুরুত্বপূর্ণ","text":"একক অভিভাবক, দত্তক বাবা-মা, নাতি-নাতনিকে বড় করা দাদু-দিদা — সব পরিবারকে স্বাগত।"},{"id":"c13","title":"ছোট কাজ, বারবার","text":"সপ্তাহে একটি ফোন বছরে একবারের বড় উদ্যোগের চেয়ে বেশি কাজ করে।"}]},{"id":"b109","kicker":"কীভাবে কাজ করে","heading":"তিনটি ধাপ, দুই মিনিট","items":[{"id":"s14","title":"একসঙ্গে সেলফি তুলুন","text":"বাড়িতে, ভিডিও কলে, অথবা তাঁরা আর না থাকলে পুরোনো ছবি দিয়ে।"},{"id":"s15","title":"এক লাইন ধন্যবাদ যোগ করুন","text":"বিশ্বকে বলুন তাঁরা আপনাকে কী শিখিয়েছেন, আমাদের ছয়টি ভাষার যেকোনোটিতে।"},{"id":"s16","title":"শেয়ার করুন আর প্রতিশ্রুতি রাখুন","text":"আমাদের ওয়ালে পোস্ট করুন, পরিবারকে পাঠান, আর সপ্তাহের জন্য একটি ছোট প্রতিশ্রুতি বেছে নিন।"}],"buttons":[{"id":"b17","label":"আপনার সেলফি শেয়ার করুন"}]},{"id":"b110","kicker":"আমাদের চিনুন","heading":"মানুষ, পথ আর কাজ","items":[{"id":"c18","title":"আমাদের প্রতিষ্ঠাতার সঙ্গে পরিচিত হন","text":"কেন একজন মানুষ ভাবলেন একটি সেলফি বাবা-মায়ের প্রতি আমাদের আচরণ বদলাতে পারে।","linkLabel":"তাঁর গল্প পড়ুন"},{"id":"c19","title":"আমাদের যাত্রা","text":"প্রথম ছবি থেকে শহর, গ্রাম আর স্কুলজুড়ে এক অভিযান পর্যন্ত।","linkLabel":"মাইলফলক দেখুন"},{"id":"c20","title":"আমরা কী করি","text":"স্বাস্থ্য শিবির, স্কুল কর্মসূচি, ডিজিটাল সহায়তা আর একা থাকা প্রবীণদের কাছে যাওয়া।","linkLabel":"আমাদের কাজ দেখুন"}]},{"id":"b111","kicker":"জেনে রাখুন","heading":"মানুষ আমাদের যা জিজ্ঞেস করেন","items":[{"id":"q21","question":"অংশ নিতে কি কোনো খরচ আছে?","answer":"না। সেলফি শেয়ার, অঙ্গীকার নেওয়া আর আমাদের কাজে যোগ দেওয়া বিনামূল্যে।"},{"id":"q22","question":"কে সেলফি শেয়ার করতে পারেন?","answer":"যে কেউ যিনি বাবা-মা, দাদু-দিদা বা অভিভাবককে ধন্যবাদ জানাতে চান। ১৮ বছরের কম বয়সীরা বাবা-মা বা অভিভাবকের মাধ্যমে শেয়ার করে।"},{"id":"q23","question":"আমার ছবির কী হয়?","answer":"প্রকাশের আগে আমাদের দল এটি যাচাই করে, শুধু যেখানে আপনি অনুমতি দেন সেখানেই দেখানো হয়, আর আপনি চাইলে যেকোনো সময় সরানো হয়।"},{"id":"q24","question":"এই অভিযান কি কোনো সরকারি প্রকল্পের সঙ্গে যুক্ত?","answer":"সেলফি উইথ প্যারেন্ট একটি স্বাধীন অভিযান। [Add any official partnerships here only once they are confirmed.]"}]},{"id":"b112","title":"এবার আপনার ধন্যবাদ জানানোর পালা","text":"এতে দুই মিনিট লাগে, আর হয়তো এই ছবিটাই তাঁরা বছরের পর বছর ফোনে রেখে দেবেন।","buttons":[{"id":"b25","label":"সেলফি শেয়ার করুন"},{"id":"b26","label":"যুক্ত হন"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_about, 'ar', N'من نحن | سيلفي مع الوالدين', N'تحوّل سيلفي مع الوالدين صورة بسيطة إلى شكر لمن ربّونا، وتحوّل ذلك الشكر إلى رعاية لكبار السن.', N'[{"id":"b104","eyebrow":"من نحن","title":"شكرٌ،","highlight":"سيلفي تلو الأخرى","lead":"سيلفي مع الوالدين حملة شعبية تحوّل صورة بسيطة إلى لحظة امتنان، وتحوّل ذلك الامتنان إلى رعاية لكبار السن من حولنا."},{"id":"b105","items":[{"id":"t100","label":"من نحن"},{"id":"t101","label":"مؤسِّسنا"},{"id":"t102","label":"رحلتنا"},{"id":"t103","label":"ماذا نفعل"}]},{"id":"b106","kicker":"من نحن","heading":"نساعد العائلات على قول ما يبقى غالبًا دون أن يُقال.","paragraphs":[{"id":"p1","text":"يشكر معظمنا والديه أقل بكثير مما يريد. سيلفي مع الوالدين تجعل الأمر سهلًا: التقط صورة معهم، وأضف سطرًا عمّا علّموك، وشاركها."},{"id":"p2","text":"تصبح كل سيلفي وعدًا صغيرًا معلنًا بالبقاء قريبين، وتذكيرًا بالاهتمام بكبار السن الذين لا يجدون من يلتقط معهم صورة."}],"facts":[{"id":"f3","text":"مجاني لكل عائلة"},{"id":"f4","text":"متاح بست لغات"},{"id":"f5","text":"الآباء والأجداد والأوصياء، كلهم يُحسبون"},{"id":"f6","text":"صورك، اختيارك — دائمًا بموافقة"}]},{"id":"b107","items":[{"id":"c7","title":"مهمتنا","text":"أن نجعل شكر الوالدين والأجداد عادة، لا رسالة مرة في السنة."},{"id":"c8","title":"رؤيتنا","text":"عالم لا يشعر فيه أي مسنّ بأنه منسيّ، سواء عاش مع عائلته أو وحده أو بعيدًا."},{"id":"c9","title":"وعدنا لك","text":"لا تُنشر أي صورة إلا بموافقة من فيها، وتُحفظ بأمان، وتُحذف متى طلبت ذلك."}]},{"id":"b108","kicker":"ما نؤمن به","heading":"أربع قيم وراء كل سيلفي","items":[{"id":"c10","title":"الامتنان أولًا","text":"نحتفي بمن ربّونا، لا بالإعجابات أو المتابعين."},{"id":"c11","title":"الموافقة والكرامة","text":"لا يظهر أحد على موقعنا دون موافقته، وخاصة كبار السن."},{"id":"c12","title":"كل عائلة تُحسب","text":"الآباء العازبون، والآباء بالتبنّي، والأجداد الذين يربّون أحفادهم — كل عائلة مرحَّب بها."},{"id":"c13","title":"أفعال صغيرة، باستمرار","text":"مكالمة أسبوعية تفعل أكثر من بادرة كبيرة مرة في السنة."}]},{"id":"b109","kicker":"كيف يعمل","heading":"ثلاث خطوات، دقيقتان","items":[{"id":"s14","title":"التقطوا سيلفي معًا","text":"في البيت، أو عبر مكالمة فيديو، أو بصورة قديمة إن لم يعودوا معك."},{"id":"s15","title":"أضف سطر شكر واحدًا","text":"أخبر العالم بشيء علّموك إياه، بأي من لغاتنا الست."},{"id":"s16","title":"شاركها وحافظ على الوعد","text":"انشرها على حائطنا، وأرسلها لعائلتك، واختر وعدًا صغيرًا للأسبوع."}],"buttons":[{"id":"b17","label":"شارك صورتك"}]},{"id":"b110","kicker":"تعرّف علينا","heading":"الأشخاص والطريق والعمل","items":[{"id":"c18","title":"تعرّف على مؤسِّسنا","text":"لماذا قرّر شخص واحد أن سيلفي يمكن أن تغيّر طريقة معاملتنا لوالدينا.","linkLabel":"اقرأ قصته"},{"id":"c19","title":"رحلتنا","text":"من الصورة الأولى إلى حملة في المدن والقرى والمدارس.","linkLabel":"شاهد المحطات"},{"id":"c20","title":"ماذا نفعل","text":"مخيمات صحية، وبرامج مدرسية، ومساعدة رقمية، وزيارات لكبار السن الذين يعيشون وحدهم.","linkLabel":"استكشف عملنا"}]},{"id":"b111","kicker":"من المفيد معرفته","heading":"أسئلة يطرحها الناس علينا","items":[{"id":"q21","question":"هل المشاركة تكلّف شيئًا؟","answer":"لا. مشاركة السيلفي، وأخذ التعهّد، والانضمام إلى أنشطتنا كلها مجانية."},{"id":"q22","question":"من يمكنه مشاركة سيلفي؟","answer":"أي شخص لديه والد أو جدّ أو وصيّ يريد شكره. من هم دون 18 عامًا يشاركون عبر أحد الوالدين أو الوصي."},{"id":"q23","question":"ماذا يحدث لصورتي؟","answer":"يراجعها فريقنا قبل ظهورها، وتُعرض فقط حيث تسمح، وتُحذف متى طلبت."},{"id":"q24","question":"هل الحملة مرتبطة ببرنامج حكومي؟","answer":"سيلفي مع الوالدين حملة مستقلة. [Add any official partnerships here only once they are confirmed.]"}]},{"id":"b112","title":"دورك لتقول شكرًا","text":"تستغرق دقيقتين، وقد تكون الصورة التي يحتفظون بها على هواتفهم لسنوات.","buttons":[{"id":"b25","label":"شارك سيلفي"},{"id":"b26","label":"شارك معنا"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_about, 'es', N'Sobre nosotros | Selfie with Parent', N'Selfie with Parent convierte una foto sencilla en un gracias a quienes nos criaron, y ese gracias en cuidado para las personas mayores.', N'[{"id":"b104","eyebrow":"Sobre nosotros","title":"Un gracias,","highlight":"selfie a selfie","lead":"Selfie with Parent es una campaña ciudadana que convierte una foto sencilla en un momento de gratitud, y esa gratitud en cuidado para los mayores que nos rodean."},{"id":"b105","items":[{"id":"t100","label":"Sobre nosotros"},{"id":"t101","label":"Nuestro fundador"},{"id":"t102","label":"Nuestro camino"},{"id":"t103","label":"Qué hacemos"}]},{"id":"b106","kicker":"Quiénes somos","heading":"Ayudamos a las familias a decir lo que a menudo se queda sin decir.","paragraphs":[{"id":"p1","text":"La mayoría damos las gracias a nuestros padres mucho menos de lo que quisiéramos. Selfie with Parent lo pone fácil: haceos una foto juntos, añade una frase sobre algo que te enseñaron y compártela."},{"id":"p2","text":"Cada selfie se convierte en una pequeña promesa pública de estar cerca, y en un recordatorio de cuidar a los mayores que no tienen con quién hacerse una foto."}],"facts":[{"id":"f3","text":"Gratis para todas las familias"},{"id":"f4","text":"Disponible en seis idiomas"},{"id":"f5","text":"Padres, abuelos y tutores: todos cuentan"},{"id":"f6","text":"Tus fotos, tu decisión, siempre con consentimiento"}]},{"id":"b107","items":[{"id":"c7","title":"Nuestra misión","text":"Que dar las gracias a padres y abuelos sea un hábito, no un mensaje una vez al año."},{"id":"c8","title":"Nuestra visión","text":"Un mundo donde ninguna persona mayor se sienta olvidada, viva con su familia, sola o lejos."},{"id":"c9","title":"Nuestra promesa","text":"Cada foto se comparte solo con el consentimiento de quienes aparecen, se guarda de forma segura y se retira cuando lo pidas."}]},{"id":"b108","kicker":"Lo que defendemos","heading":"Cuatro valores detrás de cada selfie","items":[{"id":"c10","title":"Primero, la gratitud","text":"Celebramos a quienes nos criaron, no los ''me gusta'' ni los seguidores."},{"id":"c11","title":"Consentimiento y dignidad","text":"Nadie aparece en nuestra web sin estar de acuerdo, y menos aún una persona mayor."},{"id":"c12","title":"Todas las familias cuentan","text":"Familias monoparentales, padres adoptivos, abuelos que crían a sus nietos: todas las familias son bienvenidas."},{"id":"c13","title":"Pequeños gestos, a menudo","text":"Una llamada cada semana hace más que un gran gesto una vez al año."}]},{"id":"b109","kicker":"Cómo funciona","heading":"Tres pasos, dos minutos","items":[{"id":"s14","title":"Haceos un selfie juntos","text":"En casa, en una videollamada o con una foto antigua si ya no están contigo."},{"id":"s15","title":"Añade una frase de agradecimiento","text":"Cuenta al mundo algo que te enseñaron, en cualquiera de nuestros seis idiomas."},{"id":"s16","title":"Compártelo y cumple la promesa","text":"Publícalo en nuestro muro, envíalo a tu familia y elige una pequeña promesa para la semana."}],"buttons":[{"id":"b17","label":"Comparte tu selfie"}]},{"id":"b110","kicker":"Conócenos","heading":"Las personas, el camino y el trabajo","items":[{"id":"c18","title":"Conoce a nuestro fundador","text":"Por qué una persona decidió que un selfie podía cambiar cómo tratamos a nuestros padres.","linkLabel":"Lee su historia"},{"id":"c19","title":"Nuestro camino","text":"De la primera foto a una campaña en pueblos, ciudades y escuelas.","linkLabel":"Ver los hitos"},{"id":"c20","title":"Qué hacemos","text":"Campamentos de salud, programas escolares, ayuda digital y visitas a mayores que viven solos.","linkLabel":"Descubre nuestro trabajo"}]},{"id":"b111","kicker":"Conviene saber","heading":"Preguntas que nos hacen","items":[{"id":"q21","question":"¿Cuesta algo participar?","answer":"No. Compartir un selfie, hacer el compromiso y unirte a nuestras actividades es gratis."},{"id":"q22","question":"¿Quién puede compartir un selfie?","answer":"Cualquiera que quiera dar las gracias a un padre, abuelo o tutor. Los menores de 18 comparten a través de un padre o tutor."},{"id":"q23","question":"¿Qué pasa con mi foto?","answer":"Nuestro equipo la revisa antes de publicarla, se muestra solo donde lo permitas y se retira cuando lo pidas."},{"id":"q24","question":"¿La campaña está vinculada a algún programa del gobierno?","answer":"Selfie with Parent es una campaña independiente. [Add any official partnerships here only once they are confirmed.]"}]},{"id":"b112","title":"Te toca dar las gracias","text":"Son dos minutos, y quizá sea la foto que guarden en el móvil durante años.","buttons":[{"id":"b25","label":"Comparte un selfie"},{"id":"b26","label":"Participa"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_about, 'fr', N'À propos | Selfie with Parent', N'Selfie with Parent transforme une simple photo en merci à ceux qui nous ont élevés, et ce merci en attention pour les aînés.', N'[{"id":"b104","eyebrow":"À propos","title":"Un merci,","highlight":"un selfie à la fois","lead":"Selfie with Parent est une campagne citoyenne qui transforme une simple photo en moment de gratitude, et cette gratitude en attention pour les aînés qui nous entourent."},{"id":"b105","items":[{"id":"t100","label":"À propos"},{"id":"t101","label":"Notre fondateur"},{"id":"t102","label":"Notre parcours"},{"id":"t103","label":"Nos actions"}]},{"id":"b106","kicker":"Qui nous sommes","heading":"Nous aidons les familles à dire ce qui reste souvent tu.","paragraphs":[{"id":"p1","text":"La plupart d''entre nous remercient leurs parents bien moins souvent qu''ils le voudraient. Selfie with Parent rend cela simple : prenez une photo ensemble, ajoutez une phrase sur ce qu''ils vous ont appris, et partagez-la."},{"id":"p2","text":"Chaque selfie devient une petite promesse publique de rester proches, et un rappel de veiller sur les aînés qui n''ont personne avec qui se prendre en photo."}],"facts":[{"id":"f3","text":"Gratuit pour toutes les familles"},{"id":"f4","text":"Disponible en six langues"},{"id":"f5","text":"Parents, grands-parents et tuteurs : tous comptent"},{"id":"f6","text":"Vos photos, votre choix — toujours avec consentement"}]},{"id":"b107","items":[{"id":"c7","title":"Notre mission","text":"Faire du merci à nos parents et grands-parents une habitude, pas un message une fois par an."},{"id":"c8","title":"Notre vision","text":"Un monde où aucun aîné ne se sent oublié, qu''il vive en famille, seul ou au loin."},{"id":"c9","title":"Notre promesse","text":"Chaque photo n''est partagée qu''avec l''accord des personnes qui y figurent, conservée en sécurité et retirée dès que vous le demandez."}]},{"id":"b108","kicker":"Ce que nous défendons","heading":"Quatre valeurs derrière chaque selfie","items":[{"id":"c10","title":"La gratitude d''abord","text":"Nous célébrons ceux qui nous ont élevés, pas les likes ni les abonnés."},{"id":"c11","title":"Consentement et dignité","text":"Personne n''apparaît sur notre site sans son accord, et surtout pas un aîné."},{"id":"c12","title":"Chaque famille compte","text":"Parents seuls, parents adoptifs, grands-parents qui élèvent leurs petits-enfants : toutes les familles sont les bienvenues."},{"id":"c13","title":"De petits gestes, souvent","text":"Un appel par semaine fait plus qu''un grand geste une fois par an."}]},{"id":"b109","kicker":"Comment ça marche","heading":"Trois étapes, deux minutes","items":[{"id":"s14","title":"Prenez un selfie ensemble","text":"À la maison, en appel vidéo, ou avec une ancienne photo s''ils ne sont plus là."},{"id":"s15","title":"Ajoutez une phrase de remerciement","text":"Dites au monde une chose qu''ils vous ont apprise, dans l''une de nos six langues."},{"id":"s16","title":"Partagez-le et tenez votre promesse","text":"Publiez-le sur notre mur, envoyez-le à la famille et choisissez une petite promesse pour la semaine."}],"buttons":[{"id":"b17","label":"Partagez votre selfie"}]},{"id":"b110","kicker":"Faites notre connaissance","heading":"Les personnes, le chemin et le travail","items":[{"id":"c18","title":"Rencontrez notre fondateur","text":"Pourquoi une personne a décidé qu''un selfie pouvait changer notre façon de traiter nos parents.","linkLabel":"Lire son histoire"},{"id":"c19","title":"Notre parcours","text":"De la première photo à une campagne dans les villes, les villages et les écoles.","linkLabel":"Voir les étapes"},{"id":"c20","title":"Nos actions","text":"Camps de santé, programmes scolaires, aide numérique et visites aux aînés qui vivent seuls.","linkLabel":"Découvrir notre travail"}]},{"id":"b111","kicker":"Bon à savoir","heading":"Les questions qu''on nous pose","items":[{"id":"q21","question":"Faut-il payer pour participer ?","answer":"Non. Partager un selfie, prendre l''engagement et rejoindre nos activités est gratuit."},{"id":"q22","question":"Qui peut partager un selfie ?","answer":"Toute personne qui veut remercier un parent, un grand-parent ou un tuteur. Les moins de 18 ans partagent via un parent ou tuteur."},{"id":"q23","question":"Que devient ma photo ?","answer":"Notre équipe la vérifie avant publication, elle n''apparaît que là où vous l''autorisez et elle est retirée dès que vous le demandez."},{"id":"q24","question":"La campagne est-elle liée à un programme gouvernemental ?","answer":"Selfie with Parent est une campagne indépendante. [Add any official partnerships here only once they are confirmed.]"}]},{"id":"b112","title":"À votre tour de dire merci","text":"Cela prend deux minutes, et ce sera peut-être la photo qu''ils garderont des années sur leur téléphone.","buttons":[{"id":"b25","label":"Partager un selfie"},{"id":"b26","label":"S''impliquer"}]}]');
END
GO

IF NOT EXISTS (SELECT 1 FROM [site].[Page] WHERE [Slug] = 'founder')
BEGIN
    INSERT [site].[Page] ([Slug], [IsPublished]) VALUES ('founder', 1);
    DECLARE @p_founder INT = SCOPE_IDENTITY();
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_founder, 'en', N'Our Founder | Selfie with Parent', N'Meet the founder of Selfie with Parent and read, in their own words, why they started a campaign about saying thank you.', N'[{"type":"hero","eyebrow":"Our founder","title":"The first person to","highlight":"say thank you","lead":"Why one person started a campaign about the people who raised us, in their own words.","id":"b117"},{"type":"tabs","items":[{"id":"t113","icon":"bi-heart","label":"About us","url":"/about"},{"id":"t114","icon":"bi-person","label":"Our founder","url":"/founder"},{"id":"t115","icon":"bi-signpost-split","label":"Our journey","url":"/journey"},{"id":"t116","icon":"bi-hand-thumbs-up","label":"What we do","url":"/what-we-do"}],"id":"b118"},{"type":"profile","image":"img/founder-placeholder.svg","imageAlt":"Portrait of the founder of Selfie with Parent (placeholder)","badge":"Founder","role":"Founder, Selfie with Parent","name":"[Founder Name]","intro":"Started Selfie with Parent to make thanking our parents an everyday habit. [Add one sentence about who the founder is: their work, their family, where they are from.]","note":"Design preview — replace the placeholders with the founder''s real details","facts":[{"id":"f27","label":"Background","value":"[e.g. teacher, doctor, engineer]"},{"id":"f28","label":"Based in","value":"[City, State]"},{"id":"f29","label":"Started the campaign","value":"[Year]"},{"id":"f30","label":"Favourite family ritual","value":"[e.g. Sunday lunch together]"}],"socials":[{"id":"l31","icon":"bi-linkedin","url":"","label":"LinkedIn (add link)"},{"id":"l32","icon":"bi-twitter-x","url":"","label":"X / Twitter (add link)"},{"id":"l33","icon":"bi-instagram","url":"","label":"Instagram (add link)"},{"id":"l34","icon":"bi-envelope","url":"mailto:hello@selfiewithparent.org","label":"Email"}],"id":"b119"},{"type":"letter","background":"soft","kicker":"In their own words","heading":"A letter from our founder","signature":"[Founder Name]","paragraphs":[{"id":"p35","text":"[The moment it began — describe the day, conversation or photo that made you start. Keep it personal and true.]"},{"id":"p36","text":"[Why parents and elders — what you saw around you that made this feel urgent: parents living alone, busy children, a missed birthday, a hospital visit.]"},{"id":"p37","text":"[Why a selfie — why a simple photo felt like the right way to begin, and what you hope people feel when they take one.]"},{"id":"p38","text":"[What you ask of every reader — one thing you hope each person will do this week.]"}],"id":"b120"},{"type":"quote","text":"[One line the founder lives by — for example, something their mother or father always said.]","cite":"[Founder Name]","id":"b121"},{"type":"cards","layout":"grid","columns":3,"background":"soft","kicker":"What guides the work","heading":"Principles the campaign was built on","items":[{"id":"c39","icon":"bi-ear","title":"Listen to elders","text":"Their stories, needs and wishes come first, not ours."},{"id":"c40","icon":"bi-hand-index","title":"Keep it simple","text":"If it takes more than two minutes, most people won''t do it. So we make it quick."},{"id":"c41","icon":"bi-lightning-charge","title":"Do, don''t just post","text":"Every selfie should lead to a call, a visit or a kept promise."}],"id":"b122"},{"type":"cards","layout":"grid","columns":3,"kicker":"Recognition & media","heading":"Talks, awards and coverage","intro":"Add only coverage and awards that really happened, with a link to the source.","items":[{"id":"c42","icon":"bi-newspaper","title":"[Publication name]","text":"[Headline or one-line summary, with date and link]"},{"id":"c43","icon":"bi-mic","title":"[Talk or event]","text":"[Where and when it happened]"},{"id":"c44","icon":"bi-award","title":"[Award or honour]","text":"[Who gave it, and for what]"}],"id":"b123"},{"type":"cta","title":"Want to talk to our founder?","text":"For interviews, talks and partnerships, write to us and we''ll get back within a few working days.","buttons":[{"id":"b45","label":"Request an interview","url":"mailto:hello@selfiewithparent.org?subject=Interview%20request","icon":"bi-envelope","style":"primary"},{"id":"b46","label":"See our journey","url":"/journey","icon":"bi-signpost-split","style":"secondary"}],"id":"b124"}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_founder, 'hi', N'हमारे संस्थापक | सेल्फी विद पैरेंट', N'सेल्फी विद पैरेंट के संस्थापक से मिलें और उन्हीं के शब्दों में पढ़ें कि उन्होंने धन्यवाद कहने का यह अभियान क्यों शुरू किया।', N'[{"id":"b117","eyebrow":"हमारे संस्थापक","title":"वह पहला व्यक्ति जिसने","highlight":"धन्यवाद कहा","lead":"एक व्यक्ति ने हमें पालने वालों के लिए यह अभियान क्यों शुरू किया, उन्हीं के शब्दों में।"},{"id":"b118","items":[{"id":"t113","label":"हमारे बारे में"},{"id":"t114","label":"हमारे संस्थापक"},{"id":"t115","label":"हमारा सफ़र"},{"id":"t116","label":"हम क्या करते हैं"}]},{"id":"b119","imageAlt":"सेल्फी विद पैरेंट के संस्थापक का चित्र (प्लेसहोल्डर)","badge":"संस्थापक","role":"संस्थापक, Selfie with Parent","intro":"माता-पिता को धन्यवाद कहने को रोज़ की आदत बनाने के लिए सेल्फी विद पैरेंट शुरू किया। [Add one sentence about who the founder is: their work, their family, where they are from.]","note":"डिज़ाइन पूर्वावलोकन — प्लेसहोल्डर की जगह संस्थापक की असली जानकारी डालें","facts":[{"id":"f27","label":"पृष्ठभूमि"},{"id":"f28","label":"निवास"},{"id":"f29","label":"अभियान शुरू किया"},{"id":"f30","label":"पसंदीदा पारिवारिक परंपरा"}],"socials":[{"id":"l31","label":"LinkedIn (लिंक जोड़ें)"},{"id":"l32","label":"X / Twitter (लिंक जोड़ें)"},{"id":"l33","label":"Instagram (लिंक जोड़ें)"},{"id":"l34","label":"ईमेल"}]},{"id":"b120","kicker":"उन्हीं के शब्दों में","heading":"हमारे संस्थापक का एक पत्र"},{"id":"b122","kicker":"काम का मार्गदर्शन क्या करता है","heading":"वे सिद्धांत जिन पर अभियान बना","items":[{"id":"c39","title":"बुज़ुर्गों की सुनें","text":"उनकी कहानियाँ, ज़रूरतें और इच्छाएँ पहले आती हैं, हमारी नहीं।"},{"id":"c40","title":"इसे सरल रखें","text":"अगर इसमें दो मिनट से ज़्यादा लगें तो ज़्यादातर लोग नहीं करेंगे। इसलिए हम इसे जल्दी बनाते हैं।"},{"id":"c41","title":"सिर्फ़ पोस्ट नहीं, कुछ करें","text":"हर सेल्फी के बाद एक फ़ोन, एक मुलाक़ात या एक निभाया गया वादा होना चाहिए।"}]},{"id":"b123","kicker":"सम्मान और मीडिया","heading":"व्याख्यान, पुरस्कार और कवरेज","intro":"केवल वही कवरेज और पुरस्कार जोड़ें जो सच में हुए हों, स्रोत के लिंक के साथ।"},{"id":"b124","title":"हमारे संस्थापक से बात करना चाहते हैं?","text":"साक्षात्कार, व्याख्यान और साझेदारी के लिए हमें लिखें, हम कुछ कार्यदिवसों में जवाब देंगे।","buttons":[{"id":"b45","label":"साक्षात्कार का अनुरोध करें"},{"id":"b46","label":"हमारा सफ़र देखें"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_founder, 'bn', N'আমাদের প্রতিষ্ঠাতা | সেলফি উইথ প্যারেন্ট', N'সেলফি উইথ প্যারেন্টের প্রতিষ্ঠাতার সঙ্গে পরিচিত হন আর তাঁর নিজের কথায় পড়ুন কেন তিনি ধন্যবাদ জানানোর এই অভিযান শুরু করলেন।', N'[{"id":"b117","eyebrow":"আমাদের প্রতিষ্ঠাতা","title":"প্রথম মানুষ যিনি","highlight":"ধন্যবাদ বলেছিলেন","lead":"যাঁরা আমাদের বড় করেছেন তাঁদের নিয়ে একজন মানুষ কেন এই অভিযান শুরু করলেন, তাঁর নিজের কথায়।"},{"id":"b118","items":[{"id":"t113","label":"আমাদের সম্পর্কে"},{"id":"t114","label":"আমাদের প্রতিষ্ঠাতা"},{"id":"t115","label":"আমাদের যাত্রা"},{"id":"t116","label":"আমরা কী করি"}]},{"id":"b119","imageAlt":"সেলফি উইথ প্যারেন্টের প্রতিষ্ঠাতার প্রতিকৃতি (প্লেসহোল্ডার)","badge":"প্রতিষ্ঠাতা","role":"প্রতিষ্ঠাতা, Selfie with Parent","intro":"বাবা-মাকে ধন্যবাদ জানানোকে প্রতিদিনের অভ্যাস করতে সেলফি উইথ প্যারেন্ট শুরু করেছেন। [Add one sentence about who the founder is: their work, their family, where they are from.]","note":"ডিজাইন প্রিভিউ — প্লেসহোল্ডারের জায়গায় প্রতিষ্ঠাতার আসল তথ্য দিন","facts":[{"id":"f27","label":"পটভূমি"},{"id":"f28","label":"বাস"},{"id":"f29","label":"অভিযান শুরু"},{"id":"f30","label":"প্রিয় পারিবারিক রীতি"}],"socials":[{"id":"l31","label":"LinkedIn (লিংক যোগ করুন)"},{"id":"l32","label":"X / Twitter (লিংক যোগ করুন)"},{"id":"l33","label":"Instagram (লিংক যোগ করুন)"},{"id":"l34","label":"ইমেইল"}]},{"id":"b120","kicker":"তাঁর নিজের কথায়","heading":"আমাদের প্রতিষ্ঠাতার একটি চিঠি"},{"id":"b122","kicker":"কাজের দিশা কী","heading":"যে নীতির ওপর অভিযান গড়ে উঠেছে","items":[{"id":"c39","title":"প্রবীণদের কথা শুনুন","text":"তাঁদের গল্প, প্রয়োজন আর ইচ্ছা আগে, আমাদের নয়।"},{"id":"c40","title":"সহজ রাখুন","text":"দুই মিনিটের বেশি লাগলে বেশিরভাগ মানুষ করবেন না। তাই আমরা এটা দ্রুত রাখি।"},{"id":"c41","title":"শুধু পোস্ট নয়, কিছু করুন","text":"প্রতিটি সেলফির পর একটি ফোন, একবার দেখা করা বা একটি রাখা প্রতিশ্রুতি হওয়া উচিত।"}]},{"id":"b123","kicker":"স্বীকৃতি ও গণমাধ্যম","heading":"বক্তৃতা, পুরস্কার ও সংবাদ","intro":"শুধু যে সংবাদ ও পুরস্কার সত্যিই হয়েছে সেগুলো যোগ করুন, উৎসের লিংকসহ।"},{"id":"b124","title":"আমাদের প্রতিষ্ঠাতার সঙ্গে কথা বলতে চান?","text":"সাক্ষাৎকার, বক্তৃতা ও অংশীদারির জন্য আমাদের লিখুন, কয়েক কার্যদিবসের মধ্যে উত্তর দেব।","buttons":[{"id":"b45","label":"সাক্ষাৎকারের অনুরোধ করুন"},{"id":"b46","label":"আমাদের যাত্রা দেখুন"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_founder, 'ar', N'مؤسِّسنا | سيلفي مع الوالدين', N'تعرّف على مؤسِّس سيلفي مع الوالدين واقرأ بكلماته لماذا بدأ حملة عن قول شكرًا.', N'[{"id":"b117","eyebrow":"مؤسِّسنا","title":"أول من","highlight":"قال شكرًا","lead":"لماذا بدأ شخص واحد حملة عن الذين ربّونا، بكلماته."},{"id":"b118","items":[{"id":"t113","label":"من نحن"},{"id":"t114","label":"مؤسِّسنا"},{"id":"t115","label":"رحلتنا"},{"id":"t116","label":"ماذا نفعل"}]},{"id":"b119","imageAlt":"صورة مؤسِّس سيلفي مع الوالدين (مؤقتة)","badge":"المؤسِّس","role":"المؤسس، Selfie with Parent","intro":"أسّس سيلفي مع الوالدين ليجعل شكر الوالدين عادة يومية. [Add one sentence about who the founder is: their work, their family, where they are from.]","note":"معاينة التصميم — استبدل النصوص المؤقتة بالبيانات الحقيقية للمؤسِّس","facts":[{"id":"f27","label":"الخلفية"},{"id":"f28","label":"مقيم في"},{"id":"f29","label":"بدأ الحملة"},{"id":"f30","label":"طقس عائلي مفضّل"}],"socials":[{"id":"l31","label":"LinkedIn (أضف الرابط)"},{"id":"l32","label":"X / Twitter (أضف الرابط)"},{"id":"l33","label":"Instagram (أضف الرابط)"},{"id":"l34","label":"البريد الإلكتروني"}]},{"id":"b120","kicker":"بكلماته","heading":"رسالة من مؤسِّسنا"},{"id":"b122","kicker":"ما الذي يوجّه العمل","heading":"المبادئ التي بُنيت عليها الحملة","items":[{"id":"c39","title":"أصغِ إلى كبار السن","text":"قصصهم واحتياجاتهم ورغباتهم تأتي أولًا، لا رغباتنا."},{"id":"c40","title":"اجعلها بسيطة","text":"إذا استغرق الأمر أكثر من دقيقتين فلن يفعله معظم الناس، لذلك نجعله سريعًا."},{"id":"c41","title":"افعل، لا تكتفِ بالنشر","text":"يجب أن تؤدي كل سيلفي إلى مكالمة أو زيارة أو وعد يُحفظ."}]},{"id":"b123","kicker":"التقدير والإعلام","heading":"محاضرات وجوائز وتغطية","intro":"أضف فقط التغطيات والجوائز التي حدثت فعلًا، مع رابط المصدر."},{"id":"b124","title":"تريد التحدث إلى مؤسِّسنا؟","text":"للمقابلات والمحاضرات والشراكات، راسلنا وسنرد خلال أيام عمل قليلة.","buttons":[{"id":"b45","label":"اطلب مقابلة"},{"id":"b46","label":"شاهد رحلتنا"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_founder, 'es', N'Nuestro fundador | Selfie with Parent', N'Conoce al fundador de Selfie with Parent y lee, con sus propias palabras, por qué empezó una campaña para dar las gracias.', N'[{"id":"b117","eyebrow":"Nuestro fundador","title":"La primera persona en","highlight":"dar las gracias","lead":"Por qué una persona empezó una campaña sobre quienes nos criaron, con sus propias palabras."},{"id":"b118","items":[{"id":"t113","label":"Sobre nosotros"},{"id":"t114","label":"Nuestro fundador"},{"id":"t115","label":"Nuestro camino"},{"id":"t116","label":"Qué hacemos"}]},{"id":"b119","imageAlt":"Retrato del fundador de Selfie with Parent (provisional)","badge":"Fundador","role":"Fundador/a, Selfie with Parent","intro":"Creó Selfie with Parent para que dar las gracias a nuestros padres sea un hábito diario. [Add one sentence about who the founder is: their work, their family, where they are from.]","note":"Vista previa del diseño: sustituye los marcadores por los datos reales del fundador","facts":[{"id":"f27","label":"Trayectoria"},{"id":"f28","label":"Vive en"},{"id":"f29","label":"Empezó la campaña"},{"id":"f30","label":"Ritual familiar favorito"}],"socials":[{"id":"l31","label":"LinkedIn (añade el enlace)"},{"id":"l32","label":"X / Twitter (añade el enlace)"},{"id":"l33","label":"Instagram (añade el enlace)"},{"id":"l34","label":"Correo electrónico"}]},{"id":"b120","kicker":"Con sus propias palabras","heading":"Una carta de nuestro fundador"},{"id":"b122","kicker":"Lo que guía el trabajo","heading":"Los principios sobre los que se construyó la campaña","items":[{"id":"c39","title":"Escuchar a los mayores","text":"Sus historias, necesidades y deseos van primero, no los nuestros."},{"id":"c40","title":"Que sea sencillo","text":"Si lleva más de dos minutos, la mayoría no lo hará. Por eso lo hacemos rápido."},{"id":"c41","title":"Actuar, no solo publicar","text":"Cada selfie debería llevar a una llamada, una visita o una promesa cumplida."}]},{"id":"b123","kicker":"Reconocimientos y prensa","heading":"Charlas, premios y cobertura","intro":"Añade solo coberturas y premios reales, con un enlace a la fuente."},{"id":"b124","title":"¿Quieres hablar con nuestro fundador?","text":"Para entrevistas, charlas y colaboraciones, escríbenos y te responderemos en pocos días laborables.","buttons":[{"id":"b45","label":"Solicitar una entrevista"},{"id":"b46","label":"Mira nuestro camino"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_founder, 'fr', N'Notre fondateur | Selfie with Parent', N'Rencontrez le fondateur de Selfie with Parent et découvrez, avec ses mots, pourquoi il a lancé une campagne pour dire merci.', N'[{"id":"b117","eyebrow":"Notre fondateur","title":"La première personne à","highlight":"dire merci","lead":"Pourquoi une personne a lancé une campagne pour ceux qui nous ont élevés, avec ses propres mots."},{"id":"b118","items":[{"id":"t113","label":"À propos"},{"id":"t114","label":"Notre fondateur"},{"id":"t115","label":"Notre parcours"},{"id":"t116","label":"Nos actions"}]},{"id":"b119","imageAlt":"Portrait du fondateur de Selfie with Parent (provisoire)","badge":"Fondateur","role":"Fondateur·rice, Selfie with Parent","intro":"A lancé Selfie with Parent pour faire du merci à nos parents une habitude de tous les jours. [Add one sentence about who the founder is: their work, their family, where they are from.]","note":"Aperçu — remplacez les textes provisoires par les vraies informations du fondateur","facts":[{"id":"f27","label":"Parcours"},{"id":"f28","label":"Basé à"},{"id":"f29","label":"A lancé la campagne"},{"id":"f30","label":"Rituel familial préféré"}],"socials":[{"id":"l31","label":"LinkedIn (ajouter le lien)"},{"id":"l32","label":"X / Twitter (ajouter le lien)"},{"id":"l33","label":"Instagram (ajouter le lien)"},{"id":"l34","label":"E-mail"}]},{"id":"b120","kicker":"Avec ses mots","heading":"Une lettre de notre fondateur"},{"id":"b122","kicker":"Ce qui guide le travail","heading":"Les principes sur lesquels repose la campagne","items":[{"id":"c39","title":"Écouter les aînés","text":"Leurs histoires, besoins et souhaits passent avant les nôtres."},{"id":"c40","title":"Rester simple","text":"Si cela prend plus de deux minutes, la plupart ne le feront pas. Alors on fait vite."},{"id":"c41","title":"Agir, pas seulement publier","text":"Chaque selfie devrait mener à un appel, une visite ou une promesse tenue."}]},{"id":"b123","kicker":"Distinctions et médias","heading":"Conférences, prix et couverture","intro":"N''ajoutez que des articles et prix réels, avec un lien vers la source."},{"id":"b124","title":"Vous voulez parler à notre fondateur ?","text":"Pour les interviews, conférences et partenariats, écrivez-nous : nous répondons sous quelques jours ouvrés.","buttons":[{"id":"b45","label":"Demander une interview"},{"id":"b46","label":"Voir notre parcours"}]}]');
END
GO

IF NOT EXISTS (SELECT 1 FROM [site].[Page] WHERE [Slug] = 'journey')
BEGIN
    INSERT [site].[Page] ([Slug], [IsPublished]) VALUES ('journey', 1);
    DECLARE @p_journey INT = SCOPE_IDENTITY();
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_journey, 'en', N'Our Journey | Selfie with Parent', N'How Selfie with Parent grew from one family photo into a campaign across towns, villages and schools, and where it is going next.', N'[{"type":"hero","eyebrow":"Our journey","title":"From one photo to","highlight":"a movement","lead":"How the campaign has grown so far, what we have learned along the way, and where we are heading next.","id":"b129"},{"type":"tabs","items":[{"id":"t125","icon":"bi-heart","label":"About us","url":"/about"},{"id":"t126","icon":"bi-person","label":"Our founder","url":"/founder"},{"id":"t127","icon":"bi-signpost-split","label":"Our journey","url":"/journey"},{"id":"t128","icon":"bi-hand-thumbs-up","label":"What we do","url":"/what-we-do"}],"id":"b130"},{"type":"stats","note":"Design preview — sample figures, replace with your real numbers","items":[{"id":"n47","value":25000,"suffix":"+","label":"Selfies shared"},{"id":"n48","value":320,"suffix":"","label":"Villages and towns"},{"id":"n49","value":1800,"suffix":"","label":"Elders visited"},{"id":"n50","value":45,"suffix":"","label":"Health camps"}],"id":"b131"},{"type":"timeline","background":"soft","kicker":"Milestones","heading":"How we got here","note":"Sample milestones — replace with your real dates and events","items":[{"id":"t51","year":"[Year]","icon":"bi-lightbulb","title":"The idea","text":"One family photo, and one question: when did we last really thank them?","upcoming":false},{"id":"t52","year":"[Year]","icon":"bi-camera","title":"The first selfies","text":"Friends and neighbours joined in, and the first stories of thanks were shared.","upcoming":false},{"id":"t53","year":"[Year]","icon":"bi-heart-pulse","title":"Into the villages","text":"Health camps for seniors and regular visits to elders who live alone.","upcoming":false},{"id":"t54","year":"[Year]","icon":"bi-mortarboard","title":"Schools join in","text":"Students brought grandparents into the classroom and started the school challenge.","upcoming":false},{"id":"t55","year":"[Year]","icon":"bi-globe2","title":"Online in six languages","text":"The campaign went online so families anywhere could take part in their own language.","upcoming":false},{"id":"t56","year":"Next","icon":"bi-flag","title":"Every district, every elder","text":"A selfie from every district, and an elder visited for every one shared.","upcoming":true}],"id":"b132"},{"type":"gallery","kicker":"Moments","heading":"Snapshots from the road","items":[{"id":"g57","image":"img/selfie-1.svg","alt":"Illustration: a son and his mother taking a selfie","caption":"[Caption: place and date]"},{"id":"g58","image":"img/selfie-3.svg","alt":"Illustration: grandparents with their grandchild","caption":"[Caption: place and date]"},{"id":"g59","image":"img/selfie-4.svg","alt":"Illustration: a daughter and her father smiling","caption":"[Caption: place and date]"},{"id":"g60","image":"img/selfie-6.svg","alt":"Illustration: a family photo at home","caption":"[Caption: place and date]"}],"id":"b133"},{"type":"cards","layout":"grid","columns":3,"background":"soft","kicker":"What we''ve learned","heading":"Three lessons from the journey","items":[{"id":"c61","icon":"bi-1-circle","title":"Small asks work","text":"People rarely say no to a two-minute photo, and that photo often leads to much more."},{"id":"c62","icon":"bi-2-circle","title":"Elders want to be heard","text":"A visit means most when we listen to their stories, not just take their picture."},{"id":"c63","icon":"bi-3-circle","title":"Families come in every shape","text":"Grandparents, guardians and adoptive parents deserve the same thank-you."}],"id":"b134"},{"type":"steps","style":"numbered","kicker":"The road ahead","heading":"Our goals for the next twelve months","items":[{"id":"s64","title":"Reach more families","text":"Bring the campaign to new states, towns and schools."},{"id":"s65","title":"More visits to elders","text":"Grow Adopt a Grandparent so more elders who live alone get a weekly visit."},{"id":"s66","title":"Help on every phone","text":"Run more digital help sessions so parents can stay in touch with family far away."}],"id":"b135"},{"type":"cta","title":"Be part of the next chapter","text":"Every selfie, every visit and every kept promise is a step on this journey.","buttons":[{"id":"b67","label":"Share a selfie","url":"/upload","icon":"bi-camera","style":"primary"},{"id":"b68","label":"See what we do","url":"/what-we-do","icon":"bi-hand-thumbs-up","style":"secondary"}],"id":"b136"}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_journey, 'hi', N'हमारा सफ़र | सेल्फी विद पैरेंट', N'कैसे सेल्फी विद पैरेंट एक पारिवारिक फ़ोटो से शहरों, गाँवों और स्कूलों तक फैला अभियान बना, और आगे कहाँ जा रहा है।', N'[{"id":"b129","eyebrow":"हमारा सफ़र","title":"एक फ़ोटो से","highlight":"एक आंदोलन तक","lead":"अब तक अभियान कैसे बढ़ा, रास्ते में हमने क्या सीखा, और आगे हम कहाँ जा रहे हैं।"},{"id":"b130","items":[{"id":"t125","label":"हमारे बारे में"},{"id":"t126","label":"हमारे संस्थापक"},{"id":"t127","label":"हमारा सफ़र"},{"id":"t128","label":"हम क्या करते हैं"}]},{"id":"b131","note":"डिज़ाइन पूर्वावलोकन — नमूना आँकड़े, अपने असली आँकड़े डालें","items":[{"id":"n47","label":"साझा सेल्फी"},{"id":"n48","label":"गाँव और शहर"},{"id":"n49","label":"बुज़ुर्गों से मुलाक़ात"},{"id":"n50","label":"स्वास्थ्य शिविर"}]},{"id":"b132","kicker":"पड़ाव","heading":"हम यहाँ तक कैसे पहुँचे","note":"नमूना पड़ाव — अपनी असली तारीख़ें और घटनाएँ डालें","items":[{"id":"t51","title":"विचार","text":"एक पारिवारिक फ़ोटो, और एक सवाल: हमने आख़िरी बार उन्हें सच में धन्यवाद कब कहा था?"},{"id":"t52","title":"पहली सेल्फी","text":"दोस्त और पड़ोसी जुड़े, और धन्यवाद की पहली कहानियाँ साझा हुईं।"},{"id":"t53","title":"गाँवों तक","text":"वरिष्ठ नागरिकों के लिए स्वास्थ्य शिविर और अकेले रहने वाले बुज़ुर्गों से नियमित मुलाक़ात।"},{"id":"t54","title":"स्कूल जुड़े","text":"विद्यार्थी दादा-दादी को कक्षा में लाए और स्कूल चैलेंज शुरू हुआ।"},{"id":"t55","title":"छह भाषाओं में ऑनलाइन","text":"अभियान ऑनलाइन आया ताकि कहीं भी रहने वाले परिवार अपनी भाषा में भाग ले सकें।"},{"id":"t56","title":"हर ज़िला, हर बुज़ुर्ग","text":"हर ज़िले से एक सेल्फी, और हर साझा सेल्फी के बदले एक बुज़ुर्ग से मुलाक़ात।"}]},{"id":"b133","kicker":"पल","heading":"रास्ते की झलकियाँ","items":[{"id":"g57","alt":"चित्र: एक बेटा अपनी माँ के साथ सेल्फी लेते हुए"},{"id":"g58","alt":"चित्र: दादा-दादी अपने पोते/पोती के साथ"},{"id":"g59","alt":"चित्र: एक बेटी और उसके पिता मुस्कुराते हुए"},{"id":"g60","alt":"चित्र: घर पर एक पारिवारिक फ़ोटो"}]},{"id":"b134","kicker":"हमने क्या सीखा","heading":"सफ़र से तीन सबक","items":[{"id":"c61","title":"छोटे अनुरोध काम करते हैं","text":"लोग दो मिनट की फ़ोटो के लिए शायद ही मना करते हैं, और वही फ़ोटो अक्सर बहुत आगे ले जाती है।"},{"id":"c62","title":"बुज़ुर्ग सुने जाना चाहते हैं","text":"मुलाक़ात तब सबसे ज़्यादा मायने रखती है जब हम उनकी कहानियाँ सुनें, सिर्फ़ फ़ोटो न लें।"},{"id":"c63","title":"परिवार हर रूप में होते हैं","text":"दादा-दादी, अभिभावक और गोद लेने वाले माता-पिता भी उसी धन्यवाद के हक़दार हैं।"}]},{"id":"b135","kicker":"आगे की राह","heading":"अगले बारह महीनों के हमारे लक्ष्य","items":[{"id":"s64","title":"ज़्यादा परिवारों तक पहुँचना","text":"अभियान को नए राज्यों, शहरों और स्कूलों तक ले जाना।"},{"id":"s65","title":"बुज़ुर्गों से ज़्यादा मुलाक़ातें","text":"''दादा-दादी को अपनाएं'' को बढ़ाना, ताकि अकेले रहने वाले और बुज़ुर्गों से हर हफ़्ते कोई मिलने आए।"},{"id":"s66","title":"हर फ़ोन पर मदद","text":"ज़्यादा डिजिटल मदद सत्र चलाना ताकि माता-पिता दूर रहने वाले परिवार से जुड़े रहें।"}]},{"id":"b136","title":"अगले अध्याय का हिस्सा बनें","text":"हर सेल्फी, हर मुलाक़ात और हर निभाया गया वादा इस सफ़र का एक कदम है।","buttons":[{"id":"b67","label":"सेल्फी साझा करें"},{"id":"b68","label":"देखें हम क्या करते हैं"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_journey, 'bn', N'আমাদের যাত্রা | সেলফি উইথ প্যারেন্ট', N'কীভাবে সেলফি উইথ প্যারেন্ট একটি পারিবারিক ছবি থেকে শহর, গ্রাম ও স্কুলজুড়ে অভিযান হয়ে উঠল, আর এরপর কোথায় যাচ্ছে।', N'[{"id":"b129","eyebrow":"আমাদের যাত্রা","title":"একটি ছবি থেকে","highlight":"একটি আন্দোলন","lead":"এখন পর্যন্ত অভিযান কীভাবে বেড়েছে, পথে আমরা কী শিখেছি, আর এরপর কোথায় যাচ্ছি।"},{"id":"b130","items":[{"id":"t125","label":"আমাদের সম্পর্কে"},{"id":"t126","label":"আমাদের প্রতিষ্ঠাতা"},{"id":"t127","label":"আমাদের যাত্রা"},{"id":"t128","label":"আমরা কী করি"}]},{"id":"b131","note":"ডিজাইন প্রিভিউ — নমুনা সংখ্যা, আপনার আসল সংখ্যা দিন","items":[{"id":"n47","label":"শেয়ার করা সেলফি"},{"id":"n48","label":"গ্রাম ও শহর"},{"id":"n49","label":"প্রবীণদের সঙ্গে সাক্ষাৎ"},{"id":"n50","label":"স্বাস্থ্য শিবির"}]},{"id":"b132","kicker":"মাইলফলক","heading":"আমরা কীভাবে এখানে এলাম","note":"নমুনা মাইলফলক — আপনার আসল তারিখ ও ঘটনা দিন","items":[{"id":"t51","title":"ভাবনা","text":"একটি পারিবারিক ছবি, আর একটি প্রশ্ন: শেষ কবে আমরা সত্যিই তাঁদের ধন্যবাদ দিয়েছি?"},{"id":"t52","title":"প্রথম সেলফিগুলো","text":"বন্ধু আর প্রতিবেশীরা যোগ দিলেন, আর ধন্যবাদের প্রথম গল্পগুলো শেয়ার হলো।"},{"id":"t53","title":"গ্রামে গ্রামে","text":"প্রবীণদের জন্য স্বাস্থ্য শিবির আর একা থাকা প্রবীণদের কাছে নিয়মিত যাওয়া।"},{"id":"t54","title":"স্কুল যোগ দিল","text":"ছাত্রছাত্রীরা দাদু-দিদাকে ক্লাসে নিয়ে এল আর স্কুল চ্যালেঞ্জ শুরু হলো।"},{"id":"t55","title":"ছয়টি ভাষায় অনলাইনে","text":"অভিযান অনলাইনে এল, যাতে যেকোনো জায়গার পরিবার নিজের ভাষায় অংশ নিতে পারে।"},{"id":"t56","title":"প্রতিটি জেলা, প্রতিটি প্রবীণ","text":"প্রতিটি জেলা থেকে একটি সেলফি, আর প্রতিটি শেয়ার করা সেলফির জন্য একজন প্রবীণের কাছে যাওয়া।"}]},{"id":"b133","kicker":"মুহূর্ত","heading":"পথের টুকরো ছবি","items":[{"id":"g57","alt":"ছবি: ছেলে ও তার মা সেলফি তুলছে"},{"id":"g58","alt":"ছবি: নাতি/নাতনির সঙ্গে দাদু-দিদা"},{"id":"g59","alt":"ছবি: মেয়ে ও তার বাবা হাসছে"},{"id":"g60","alt":"ছবি: বাড়িতে একটি পারিবারিক ছবি"}]},{"id":"b134","kicker":"আমরা কী শিখেছি","heading":"যাত্রা থেকে তিনটি শিক্ষা","items":[{"id":"c61","title":"ছোট অনুরোধ কাজ করে","text":"দুই মিনিটের একটি ছবিতে মানুষ খুব কমই না বলেন, আর সেই ছবি প্রায়ই অনেক দূর নিয়ে যায়।"},{"id":"c62","title":"প্রবীণরা শোনা চান","text":"দেখা করা সবচেয়ে অর্থবহ হয় যখন আমরা তাঁদের গল্প শুনি, শুধু ছবি তুলি না।"},{"id":"c63","title":"পরিবার নানা রকমের","text":"দাদু-দিদা, অভিভাবক আর দত্তক বাবা-মাও একই ধন্যবাদের যোগ্য।"}]},{"id":"b135","kicker":"সামনের পথ","heading":"আগামী বারো মাসের লক্ষ্য","items":[{"id":"s64","title":"আরও পরিবারের কাছে পৌঁছানো","text":"অভিযানকে নতুন রাজ্য, শহর আর স্কুলে নিয়ে যাওয়া।"},{"id":"s65","title":"প্রবীণদের কাছে আরও বেশি যাওয়া","text":"''দাদু-দিদাকে দত্তক নিন'' বাড়ানো, যাতে একা থাকা আরও প্রবীণের কাছে প্রতি সপ্তাহে কেউ যায়।"},{"id":"s66","title":"প্রতিটি ফোনে সাহায্য","text":"আরও ডিজিটাল সহায়তা সেশন চালানো, যাতে বাবা-মা দূরের পরিবারের সঙ্গে যোগাযোগ রাখতে পারেন।"}]},{"id":"b136","title":"পরের অধ্যায়ের অংশ হোন","text":"প্রতিটি সেলফি, প্রতিটি সাক্ষাৎ আর প্রতিটি রাখা প্রতিশ্রুতি এই যাত্রার একটি ধাপ।","buttons":[{"id":"b67","label":"সেলফি শেয়ার করুন"},{"id":"b68","label":"দেখুন আমরা কী করি"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_journey, 'ar', N'رحلتنا | سيلفي مع الوالدين', N'كيف نمت سيلفي مع الوالدين من صورة عائلية واحدة إلى حملة في المدن والقرى والمدارس، وإلى أين تتجه.', N'[{"id":"b129","eyebrow":"رحلتنا","title":"من صورة واحدة إلى","highlight":"حركة","lead":"كيف نمت الحملة حتى الآن، وما تعلّمناه في الطريق، وإلى أين نتجه."},{"id":"b130","items":[{"id":"t125","label":"من نحن"},{"id":"t126","label":"مؤسِّسنا"},{"id":"t127","label":"رحلتنا"},{"id":"t128","label":"ماذا نفعل"}]},{"id":"b131","note":"معاينة التصميم — أرقام تجريبية، استبدلها بأرقامك الحقيقية","items":[{"id":"n47","label":"صور مُشاركة"},{"id":"n48","label":"قرى ومدن"},{"id":"n49","label":"مسنّون تمت زيارتهم"},{"id":"n50","label":"مخيمات صحية"}]},{"id":"b132","kicker":"محطات","heading":"كيف وصلنا إلى هنا","note":"محطات تجريبية — استبدلها بتواريخك وأحداثك الحقيقية","items":[{"id":"t51","title":"الفكرة","text":"صورة عائلية واحدة، وسؤال واحد: متى شكرناهم فعلًا آخر مرة؟"},{"id":"t52","title":"أولى صور السيلفي","text":"انضمّ الأصدقاء والجيران، وشُورِكت أولى قصص الشكر."},{"id":"t53","title":"إلى القرى","text":"مخيمات صحية لكبار السن وزيارات منتظمة لمن يعيشون وحدهم."},{"id":"t54","title":"المدارس تنضم","text":"أحضر الطلاب أجدادهم إلى الصفوف وبدأ تحدي المدارس."},{"id":"t55","title":"على الإنترنت بست لغات","text":"انتقلت الحملة إلى الإنترنت لتشارك العائلات في أي مكان بلغتها."},{"id":"t56","title":"كل منطقة، كل مسنّ","text":"سيلفي من كل منطقة، وزيارة لمسنّ مقابل كل سيلفي تُشارَك."}]},{"id":"b133","kicker":"لحظات","heading":"لقطات من الطريق","items":[{"id":"g57","alt":"رسم: ابن وأمه يلتقطان سيلفي"},{"id":"g58","alt":"رسم: جدّان مع حفيدهما"},{"id":"g59","alt":"رسم: ابنة وأبوها يبتسمان"},{"id":"g60","alt":"رسم: صورة عائلية في البيت"}]},{"id":"b134","kicker":"ما تعلّمناه","heading":"ثلاثة دروس من الرحلة","items":[{"id":"c61","title":"الطلبات الصغيرة تنجح","text":"نادرًا ما يرفض الناس صورة تستغرق دقيقتين، وغالبًا ما تقود تلك الصورة إلى أكثر بكثير."},{"id":"c62","title":"كبار السن يريدون أن يُسمَعوا","text":"تكون الزيارة أعمق أثرًا حين نصغي إلى قصصهم، لا حين نلتقط صورتهم فقط."},{"id":"c63","title":"للعائلات أشكال كثيرة","text":"الأجداد والأوصياء والآباء بالتبنّي يستحقون الشكر نفسه."}]},{"id":"b135","kicker":"الطريق أمامنا","heading":"أهدافنا للأشهر الاثني عشر القادمة","items":[{"id":"s64","title":"الوصول إلى عائلات أكثر","text":"نقل الحملة إلى ولايات ومدن ومدارس جديدة."},{"id":"s65","title":"زيارات أكثر لكبار السن","text":"توسيع «تبنَّ جدًّا» ليحظى مزيد من كبار السن الذين يعيشون وحدهم بزيارة أسبوعية."},{"id":"s66","title":"مساعدة على كل هاتف","text":"تنظيم مزيد من جلسات المساعدة الرقمية ليبقى الآباء على تواصل مع عائلاتهم البعيدة."}]},{"id":"b136","title":"كن جزءًا من الفصل القادم","text":"كل سيلفي، وكل زيارة، وكل وعد محفوظ خطوة في هذه الرحلة.","buttons":[{"id":"b67","label":"شارك سيلفي"},{"id":"b68","label":"شاهد ما نفعله"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_journey, 'es', N'Nuestro camino | Selfie with Parent', N'Cómo Selfie with Parent pasó de una foto familiar a una campaña en pueblos, ciudades y escuelas, y hacia dónde va.', N'[{"id":"b129","eyebrow":"Nuestro camino","title":"De una foto a","highlight":"un movimiento","lead":"Cómo ha crecido la campaña, lo que hemos aprendido por el camino y hacia dónde vamos."},{"id":"b130","items":[{"id":"t125","label":"Sobre nosotros"},{"id":"t126","label":"Nuestro fundador"},{"id":"t127","label":"Nuestro camino"},{"id":"t128","label":"Qué hacemos"}]},{"id":"b131","note":"Vista previa: cifras de ejemplo, sustitúyelas por las reales","items":[{"id":"n47","label":"Selfies compartidos"},{"id":"n48","label":"Pueblos y ciudades"},{"id":"n49","label":"Mayores visitados"},{"id":"n50","label":"Jornadas de salud"}]},{"id":"b132","kicker":"Hitos","heading":"Cómo llegamos hasta aquí","note":"Hitos de ejemplo: sustitúyelos por tus fechas y hechos reales","items":[{"id":"t51","title":"La idea","text":"Una foto familiar y una pregunta: ¿cuándo fue la última vez que de verdad les dimos las gracias?"},{"id":"t52","title":"Los primeros selfies","text":"Amigos y vecinos se sumaron y se compartieron las primeras historias de agradecimiento."},{"id":"t53","title":"Hacia los pueblos","text":"Campamentos de salud para mayores y visitas regulares a quienes viven solos."},{"id":"t54","title":"Se suman las escuelas","text":"Los estudiantes llevaron a sus abuelos a clase y empezó el reto escolar."},{"id":"t55","title":"En línea en seis idiomas","text":"La campaña llegó a internet para que familias de cualquier lugar participen en su idioma."},{"id":"t56","title":"Cada distrito, cada mayor","text":"Un selfie de cada distrito y una visita a una persona mayor por cada uno compartido."}]},{"id":"b133","kicker":"Momentos","heading":"Instantáneas del camino","items":[{"id":"g57","alt":"Ilustración: un hijo y su madre haciéndose un selfie"},{"id":"g58","alt":"Ilustración: abuelos con su nieto"},{"id":"g59","alt":"Ilustración: una hija y su padre sonriendo"},{"id":"g60","alt":"Ilustración: una foto familiar en casa"}]},{"id":"b134","kicker":"Lo que hemos aprendido","heading":"Tres lecciones del camino","items":[{"id":"c61","title":"Lo pequeño funciona","text":"Casi nadie dice que no a una foto de dos minutos, y esa foto a menudo lleva a mucho más."},{"id":"c62","title":"Los mayores quieren ser escuchados","text":"Una visita significa más cuando escuchamos sus historias, no solo cuando les hacemos una foto."},{"id":"c63","title":"Hay familias de todo tipo","text":"Abuelos, tutores y padres adoptivos merecen el mismo agradecimiento."}]},{"id":"b135","kicker":"El camino por delante","heading":"Nuestros objetivos para los próximos doce meses","items":[{"id":"s64","title":"Llegar a más familias","text":"Llevar la campaña a nuevos estados, ciudades y escuelas."},{"id":"s65","title":"Más visitas a mayores","text":"Ampliar Adopta un abuelo para que más mayores que viven solos reciban una visita semanal."},{"id":"s66","title":"Ayuda en cada móvil","text":"Organizar más sesiones de ayuda digital para que los padres sigan en contacto con la familia lejana."}]},{"id":"b136","title":"Forma parte del próximo capítulo","text":"Cada selfie, cada visita y cada promesa cumplida es un paso en este camino.","buttons":[{"id":"b67","label":"Comparte un selfie"},{"id":"b68","label":"Mira lo que hacemos"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_journey, 'fr', N'Notre parcours | Selfie with Parent', N'Comment Selfie with Parent est passé d''une photo de famille à une campagne dans les villes, villages et écoles, et où elle va ensuite.', N'[{"id":"b129","eyebrow":"Notre parcours","title":"D''une photo à","highlight":"un mouvement","lead":"Comment la campagne a grandi, ce que nous avons appris en chemin et où nous allons."},{"id":"b130","items":[{"id":"t125","label":"À propos"},{"id":"t126","label":"Notre fondateur"},{"id":"t127","label":"Notre parcours"},{"id":"t128","label":"Nos actions"}]},{"id":"b131","note":"Aperçu — chiffres d''exemple, remplacez-les par les vrais","items":[{"id":"n47","label":"Selfies partagés"},{"id":"n48","label":"Villages et villes"},{"id":"n49","label":"Aînés visités"},{"id":"n50","label":"Bilans de santé"}]},{"id":"b132","kicker":"Étapes","heading":"Comment nous en sommes arrivés là","note":"Étapes d''exemple — remplacez-les par vos vraies dates et événements","items":[{"id":"t51","title":"L''idée","text":"Une photo de famille, et une question : quand les avons-nous vraiment remerciés pour la dernière fois ?"},{"id":"t52","title":"Les premiers selfies","text":"Amis et voisins se sont joints, et les premières histoires de remerciement ont été partagées."},{"id":"t53","title":"Vers les villages","text":"Des camps de santé pour les seniors et des visites régulières aux aînés qui vivent seuls."},{"id":"t54","title":"Les écoles s''y mettent","text":"Les élèves ont invité leurs grands-parents en classe et lancé le défi des écoles."},{"id":"t55","title":"En ligne en six langues","text":"La campagne est passée en ligne pour que les familles, partout, participent dans leur langue."},{"id":"t56","title":"Chaque district, chaque aîné","text":"Un selfie de chaque district, et un aîné visité pour chaque selfie partagé."}]},{"id":"b133","kicker":"Moments","heading":"Instantanés de la route","items":[{"id":"g57","alt":"Illustration : un fils et sa mère prennent un selfie"},{"id":"g58","alt":"Illustration : des grands-parents avec leur petit-enfant"},{"id":"g59","alt":"Illustration : une fille et son père souriants"},{"id":"g60","alt":"Illustration : une photo de famille à la maison"}]},{"id":"b134","kicker":"Ce que nous avons appris","heading":"Trois leçons du parcours","items":[{"id":"c61","title":"Les petites demandes marchent","text":"On refuse rarement une photo de deux minutes, et cette photo mène souvent bien plus loin."},{"id":"c62","title":"Les aînés veulent être écoutés","text":"Une visite compte le plus quand on écoute leurs histoires, pas seulement quand on les photographie."},{"id":"c63","title":"Les familles ont toutes les formes","text":"Grands-parents, tuteurs et parents adoptifs méritent le même merci."}]},{"id":"b135","kicker":"La route à venir","heading":"Nos objectifs pour les douze prochains mois","items":[{"id":"s64","title":"Toucher plus de familles","text":"Porter la campagne dans de nouveaux États, villes et écoles."},{"id":"s65","title":"Plus de visites aux aînés","text":"Développer Adoptez un grand-parent pour que plus d''aînés seuls reçoivent une visite chaque semaine."},{"id":"s66","title":"De l''aide sur chaque téléphone","text":"Organiser plus d''ateliers numériques pour que les parents restent en contact avec la famille éloignée."}]},{"id":"b136","title":"Faites partie du prochain chapitre","text":"Chaque selfie, chaque visite et chaque promesse tenue est un pas sur ce chemin.","buttons":[{"id":"b67","label":"Partager un selfie"},{"id":"b68","label":"Voir ce que nous faisons"}]}]');
END
GO

IF NOT EXISTS (SELECT 1 FROM [site].[Page] WHERE [Slug] = 'what-we-do')
BEGIN
    INSERT [site].[Page] ([Slug], [IsPublished]) VALUES ('what-we-do', 1);
    DECLARE @p_what_we_do INT = SCOPE_IDENTITY();
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_what_we_do, 'en', N'What We Do | Selfie with Parent', N'Health camps for seniors, school programmes, help with rights and digital skills, and visits to elders who live alone. See how Selfie with Parent turns gratitude into care.', N'[{"type":"hero","eyebrow":"What we do","title":"Gratitude that","highlight":"turns into care","lead":"The selfie is where it starts. Here is everything that happens after it.","id":"b141"},{"type":"tabs","items":[{"id":"t137","icon":"bi-heart","label":"About us","url":"/about"},{"id":"t138","icon":"bi-person","label":"Our founder","url":"/founder"},{"id":"t139","icon":"bi-signpost-split","label":"Our journey","url":"/journey"},{"id":"t140","icon":"bi-hand-thumbs-up","label":"What we do","url":"/what-we-do"}],"id":"b142"},{"type":"steps","style":"flow","kicker":"How change happens","heading":"From a photo to a habit of care","items":[{"id":"s69","icon":"bi-eye","title":"Notice","text":"A selfie makes us stop and really look at the people who raised us."},{"id":"s70","icon":"bi-chat-heart","title":"Thank","text":"One line of thanks says what we too often leave unsaid."},{"id":"s71","icon":"bi-hand-thumbs-up","title":"Act","text":"A promise follows: a weekly call, a shared meal, a visit."},{"id":"s72","icon":"bi-infinity","title":"Stay close","text":"Small acts, repeated, keep families and communities connected."}],"id":"b143"},{"type":"cards","layout":"programmes","columns":2,"background":"soft","kicker":"Our programmes","heading":"Four ways we care for elders","items":[{"id":"c85","icon":"bi-heart-pulse","title":"Elder health","text":"Free check-up camps and medicine support for senior citizens in rural areas.","bullets":[{"id":"i73","text":"Blood pressure, sugar and eye check-ups"},{"id":"i74","text":"Help to follow up with a local doctor"},{"id":"i75","text":"Reminders for medicines and appointments"}]},{"id":"c86","icon":"bi-people","title":"Bridging generations","text":"School programmes that bring grandparents into classrooms to share skills and stories.","bullets":[{"id":"i76","text":"Grandparents'' day in schools and colleges"},{"id":"i77","text":"Students record family stories and recipes"},{"id":"i78","text":"The yearly school selfie challenge"}]},{"id":"c87","icon":"bi-shield-check","title":"Rights and dignity","text":"Helping elders understand pension, welfare schemes and protection against neglect.","bullets":[{"id":"i79","text":"Simple guides to pensions and benefits"},{"id":"i80","text":"Help with forms and documents"},{"id":"i81","text":"Pointing families to legal and support services"}]},{"id":"c88","icon":"bi-phone","title":"Digital inclusion","text":"Teaching parents to video-call, pay bills and stay connected with family far away.","bullets":[{"id":"i82","text":"Phone help sessions run by volunteers"},{"id":"i83","text":"Spotting online scams and fake calls"},{"id":"i84","text":"Video calls with family living far away"}]}],"id":"b144"},{"type":"cards","layout":"activities","columns":3,"kicker":"On this website","heading":"Ways to take part today","items":[{"id":"c89","icon":"bi-camera","title":"Share a selfie","text":"Post a photo with your parent and one line of thanks.","url":"/upload"},{"id":"c90","icon":"bi-arrow-left-right","title":"Then & Now","text":"Put an old photo next to a new one.","url":"/then-now"},{"id":"c91","icon":"bi-flower1","title":"Memory Wall","text":"Remember a parent who is no longer with us.","url":"/memories"},{"id":"c92","icon":"bi-diagram-3","title":"Family Tree","text":"Build your family tree, one selfie at a time.","url":"/family-tree"},{"id":"c93","icon":"bi-mortarboard","title":"School challenge","text":"Bring the campaign to your school or college.","url":"/impact"},{"id":"c94","icon":"bi-hand-thumbs-up","title":"Take the pledge","text":"Pick one promise to keep every week.","url":"/impact"}],"id":"b145"},{"type":"cards","layout":"bento","background":"soft","anchor":"get-involved","kicker":"Get involved","heading":"There''s a place for everyone","items":[{"id":"c95","icon":"bi-person-heart","title":"Volunteer","text":"Spend an hour a week with an elder who lives alone, or help at a health camp near you.","style":"dark","width":6,"url":"/impact","linkLabel":"Adopt a Grandparent"},{"id":"c96","icon":"bi-building","title":"Partner with us","text":"Schools, hospitals, companies and community groups can run the campaign with us.","style":"gold","width":6,"url":"mailto:hello@selfiewithparent.org?subject=Partnership","linkLabel":"Write to us"},{"id":"c97","icon":"bi-megaphone","title":"Spread the word","text":"Share the campaign with your family group, your school or your workplace. The more people say thank you, the more elders feel seen.","style":"plain","width":12}],"id":"b146"},{"type":"cta","title":"It starts with one selfie","text":"Take it today, and let it be the start of something that lasts.","buttons":[{"id":"b98","label":"Share a selfie","url":"/upload","icon":"bi-camera","style":"primary"},{"id":"b99","label":"About us","url":"/about","icon":"bi-heart","style":"secondary"}],"id":"b147"}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_what_we_do, 'hi', N'हम क्या करते हैं | सेल्फी विद पैरेंट', N'वरिष्ठ नागरिकों के लिए स्वास्थ्य शिविर, स्कूल कार्यक्रम, अधिकारों और डिजिटल कौशल में मदद, और अकेले रहने वाले बुज़ुर्गों से मुलाक़ात। देखें कैसे सेल्फी विद पैरेंट आभार को देखभाल में बदलता है।', N'[{"id":"b141","eyebrow":"हम क्या करते हैं","title":"आभार जो","highlight":"देखभाल बन जाता है","lead":"सेल्फी से शुरुआत होती है। यहाँ वह सब है जो उसके बाद होता है।"},{"id":"b142","items":[{"id":"t137","label":"हमारे बारे में"},{"id":"t138","label":"हमारे संस्थापक"},{"id":"t139","label":"हमारा सफ़र"},{"id":"t140","label":"हम क्या करते हैं"}]},{"id":"b143","kicker":"बदलाव कैसे आता है","heading":"एक फ़ोटो से देखभाल की आदत तक","items":[{"id":"s69","title":"ध्यान दें","text":"एक सेल्फी हमें रुककर उन लोगों को सच में देखने पर मजबूर करती है जिन्होंने हमें पाला।"},{"id":"s70","title":"धन्यवाद कहें","text":"धन्यवाद की एक पंक्ति वह कह देती है जो हम अक्सर अनकहा छोड़ देते हैं।"},{"id":"s71","title":"कुछ करें","text":"फिर एक वादा: हर हफ़्ते एक फ़ोन, साथ में खाना, एक मुलाक़ात।"},{"id":"s72","title":"जुड़े रहें","text":"छोटे काम, बार-बार किए जाएँ, तो परिवार और समुदाय जुड़े रहते हैं।"}]},{"id":"b144","kicker":"हमारे कार्यक्रम","heading":"बुज़ुर्गों की देखभाल के चार तरीके","items":[{"id":"c85","title":"बुज़ुर्गों का स्वास्थ्य","text":"ग्रामीण क्षेत्रों में वरिष्ठ नागरिकों के लिए मुफ़्त जाँच शिविर और दवा सहायता।","bullets":[{"id":"i73","text":"ब्लड प्रेशर, शुगर और आँखों की जाँच"},{"id":"i74","text":"स्थानीय डॉक्टर से आगे की जाँच में मदद"},{"id":"i75","text":"दवाइयों और अपॉइंटमेंट के रिमाइंडर"}]},{"id":"c86","title":"पीढ़ियों को जोड़ना","text":"स्कूल कार्यक्रम जिनमें दादा-दादी कक्षाओं में आकर हुनर और कहानियाँ बाँटते हैं।","bullets":[{"id":"i76","text":"स्कूलों और कॉलेजों में दादा-दादी दिवस"},{"id":"i77","text":"विद्यार्थी पारिवारिक कहानियाँ और व्यंजन रिकॉर्ड करते हैं"},{"id":"i78","text":"सालाना स्कूल सेल्फी चैलेंज"}]},{"id":"c87","title":"अधिकार और सम्मान","text":"बुज़ुर्गों को पेंशन, कल्याण योजनाओं और उपेक्षा से सुरक्षा को समझने में मदद।","bullets":[{"id":"i79","text":"पेंशन और लाभों की आसान जानकारी"},{"id":"i80","text":"फ़ॉर्म और दस्तावेज़ों में मदद"},{"id":"i81","text":"परिवारों को क़ानूनी और सहायता सेवाओं तक पहुँचाना"}]},{"id":"c88","title":"डिजिटल समावेशन","text":"माता-पिता को वीडियो कॉल करना, बिल भरना और दूर रहने वाले परिवार से जुड़े रहना सिखाना।","bullets":[{"id":"i82","text":"स्वयंसेवकों द्वारा फ़ोन मदद सत्र"},{"id":"i83","text":"ऑनलाइन धोखाधड़ी और फ़र्ज़ी कॉल पहचानना"},{"id":"i84","text":"दूर रहने वाले परिवार से वीडियो कॉल"}]}]},{"id":"b145","kicker":"इस वेबसाइट पर","heading":"आज ही भाग लेने के तरीके","items":[{"id":"c89","title":"सेल्फी साझा करें","text":"अपने माता-पिता के साथ फ़ोटो और धन्यवाद की एक पंक्ति पोस्ट करें।"},{"id":"c90","title":"तब और अब","text":"एक पुरानी फ़ोटो को नई फ़ोटो के साथ रखें।"},{"id":"c91","title":"यादों की दीवार","text":"उन माता-पिता को याद करें जो अब हमारे साथ नहीं हैं।"},{"id":"c92","title":"वंश वृक्ष","text":"एक-एक सेल्फी से अपना वंश वृक्ष बनाएं।"},{"id":"c93","title":"स्कूल चैलेंज","text":"अभियान को अपने स्कूल या कॉलेज में लाएं।"},{"id":"c94","title":"संकल्प लें","text":"हर हफ़्ते निभाने के लिए एक वादा चुनें।"}]},{"id":"b146","kicker":"जुड़ें","heading":"हर किसी के लिए जगह है","items":[{"id":"c95","title":"स्वयंसेवक बनें","text":"हफ़्ते में एक घंटा किसी अकेले रहने वाले बुज़ुर्ग के साथ बिताएँ, या पास के स्वास्थ्य शिविर में मदद करें।","linkLabel":"एक बुज़ुर्ग को अपनाएं"},{"id":"c96","title":"हमारे साथ साझेदारी करें","text":"स्कूल, अस्पताल, कंपनियाँ और सामुदायिक समूह हमारे साथ यह अभियान चला सकते हैं।","linkLabel":"हमें लिखें"},{"id":"c97","title":"बात फैलाएं","text":"अभियान को अपने परिवार के ग्रुप, स्कूल या कार्यस्थल पर साझा करें। जितने ज़्यादा लोग धन्यवाद कहेंगे, उतना ज़्यादा बुज़ुर्ग ख़ुद को देखा हुआ महसूस करेंगे।"}]},{"id":"b147","title":"शुरुआत एक सेल्फी से होती है","text":"आज ही लें, और इसे किसी स्थायी चीज़ की शुरुआत बनने दें।","buttons":[{"id":"b98","label":"सेल्फी साझा करें"},{"id":"b99","label":"हमारे बारे में"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_what_we_do, 'bn', N'আমরা কী করি | সেলফি উইথ প্যারেন্ট', N'প্রবীণদের জন্য স্বাস্থ্য শিবির, স্কুল কর্মসূচি, অধিকার ও ডিজিটাল দক্ষতায় সাহায্য, আর একা থাকা প্রবীণদের কাছে যাওয়া। দেখুন সেলফি উইথ প্যারেন্ট কীভাবে কৃতজ্ঞতাকে যত্নে বদলায়।', N'[{"id":"b141","eyebrow":"আমরা কী করি","title":"কৃতজ্ঞতা যা","highlight":"যত্নে বদলে যায়","lead":"সেলফি দিয়ে শুরু। এরপর যা যা হয়, সব এখানে।"},{"id":"b142","items":[{"id":"t137","label":"আমাদের সম্পর্কে"},{"id":"t138","label":"আমাদের প্রতিষ্ঠাতা"},{"id":"t139","label":"আমাদের যাত্রা"},{"id":"t140","label":"আমরা কী করি"}]},{"id":"b143","kicker":"পরিবর্তন কীভাবে আসে","heading":"একটি ছবি থেকে যত্নের অভ্যাস","items":[{"id":"s69","title":"লক্ষ করুন","text":"একটি সেলফি আমাদের থেমে সত্যিই তাঁদের দিকে তাকাতে বাধ্য করে, যাঁরা আমাদের বড় করেছেন।"},{"id":"s70","title":"ধন্যবাদ দিন","text":"এক লাইনের ধন্যবাদ সেই কথা বলে দেয় যা আমরা প্রায়ই বলি না।"},{"id":"s71","title":"কিছু করুন","text":"এরপর একটি প্রতিশ্রুতি: সাপ্তাহিক ফোন, একসঙ্গে খাওয়া, একবার দেখা করা।"},{"id":"s72","title":"কাছে থাকুন","text":"ছোট কাজ বারবার করলে পরিবার আর সমাজ জুড়ে থাকে।"}]},{"id":"b144","kicker":"আমাদের কর্মসূচি","heading":"প্রবীণদের যত্নের চারটি উপায়","items":[{"id":"c85","title":"প্রবীণদের স্বাস্থ্য","text":"গ্রামীণ এলাকার প্রবীণ নাগরিকদের জন্য বিনামূল্যে স্বাস্থ্য পরীক্ষা ও ওষুধ সহায়তা।","bullets":[{"id":"i73","text":"রক্তচাপ, সুগার আর চোখ পরীক্ষা"},{"id":"i74","text":"স্থানীয় চিকিৎসকের কাছে পরবর্তী দেখানোয় সাহায্য"},{"id":"i75","text":"ওষুধ ও অ্যাপয়েন্টমেন্টের রিমাইন্ডার"}]},{"id":"c86","title":"প্রজন্মের সেতুবন্ধন","text":"স্কুল কর্মসূচি যেখানে দাদু-দিদারা ক্লাসে এসে দক্ষতা ও গল্প ভাগ করেন।","bullets":[{"id":"i76","text":"স্কুল-কলেজে দাদু-দিদা দিবস"},{"id":"i77","text":"ছাত্রছাত্রীরা পারিবারিক গল্প ও রান্নার রেসিপি রেকর্ড করে"},{"id":"i78","text":"বার্ষিক স্কুল সেলফি চ্যালেঞ্জ"}]},{"id":"c87","title":"অধিকার ও মর্যাদা","text":"প্রবীণদের পেনশন, কল্যাণ প্রকল্প ও অবহেলা থেকে সুরক্ষা বুঝতে সাহায্য।","bullets":[{"id":"i79","text":"পেনশন ও সুবিধার সহজ নির্দেশিকা"},{"id":"i80","text":"ফর্ম ও কাগজপত্রে সাহায্য"},{"id":"i81","text":"পরিবারকে আইনি ও সহায়তা পরিষেবার খোঁজ দেওয়া"}]},{"id":"c88","title":"ডিজিটাল অন্তর্ভুক্তি","text":"বাবা-মাকে ভিডিও কল, বিল পরিশোধ এবং দূরের পরিবারের সঙ্গে যুক্ত থাকতে শেখানো।","bullets":[{"id":"i82","text":"স্বেচ্ছাসেবকদের ফোন সহায়তা সেশন"},{"id":"i83","text":"অনলাইন প্রতারণা ও ভুয়া কল চেনা"},{"id":"i84","text":"দূরে থাকা পরিবারের সঙ্গে ভিডিও কল"}]}]},{"id":"b145","kicker":"এই ওয়েবসাইটে","heading":"আজই অংশ নেওয়ার উপায়","items":[{"id":"c89","title":"সেলফি শেয়ার করুন","text":"বাবা-মায়ের সঙ্গে একটি ছবি আর এক লাইন ধন্যবাদ পোস্ট করুন।"},{"id":"c90","title":"তখন ও এখন","text":"একটি পুরোনো ছবি নতুন ছবির পাশে রাখুন।"},{"id":"c91","title":"স্মৃতির দেয়াল","text":"যে বাবা-মা আর আমাদের মধ্যে নেই, তাঁদের স্মরণ করুন।"},{"id":"c92","title":"পারিবারিক বংশতালিকা","text":"একটি করে সেলফিতে আপনার বংশতালিকা তৈরি করুন।"},{"id":"c93","title":"স্কুল চ্যালেঞ্জ","text":"অভিযানকে আপনার স্কুল বা কলেজে নিয়ে আসুন।"},{"id":"c94","title":"অঙ্গীকার নিন","text":"প্রতি সপ্তাহে রাখার জন্য একটি প্রতিশ্রুতি বেছে নিন।"}]},{"id":"b146","kicker":"যুক্ত হন","heading":"সবার জন্য জায়গা আছে","items":[{"id":"c95","title":"স্বেচ্ছাসেবক হোন","text":"সপ্তাহে এক ঘণ্টা একা থাকা কোনো প্রবীণের সঙ্গে কাটান, বা কাছের স্বাস্থ্য শিবিরে সাহায্য করুন।","linkLabel":"একজন প্রবীণকে আপন করুন"},{"id":"c96","title":"আমাদের অংশীদার হোন","text":"স্কুল, হাসপাতাল, কোম্পানি আর সামাজিক সংগঠন আমাদের সঙ্গে এই অভিযান চালাতে পারে।","linkLabel":"আমাদের লিখুন"},{"id":"c97","title":"কথাটা ছড়িয়ে দিন","text":"অভিযানটি পরিবারের গ্রুপে, স্কুলে বা কর্মস্থলে শেয়ার করুন। যত বেশি মানুষ ধন্যবাদ জানাবেন, তত বেশি প্রবীণ নিজেকে গুরুত্বপূর্ণ মনে করবেন।"}]},{"id":"b147","title":"শুরু হয় একটি সেলফি দিয়ে","text":"আজই তুলুন, আর এটি হোক দীর্ঘস্থায়ী কিছুর শুরু।","buttons":[{"id":"b98","label":"সেলফি শেয়ার করুন"},{"id":"b99","label":"আমাদের সম্পর্কে"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_what_we_do, 'ar', N'ماذا نفعل | سيلفي مع الوالدين', N'مخيمات صحية لكبار السن، وبرامج مدرسية، ومساعدة في الحقوق والمهارات الرقمية، وزيارات لمن يعيشون وحدهم. شاهد كيف تحوّل سيلفي مع الوالدين الامتنان إلى رعاية.', N'[{"id":"b141","eyebrow":"ماذا نفعل","title":"امتنانٌ","highlight":"يتحوّل إلى رعاية","lead":"تبدأ القصة بالسيلفي. إليك كل ما يحدث بعدها."},{"id":"b142","items":[{"id":"t137","label":"من نحن"},{"id":"t138","label":"مؤسِّسنا"},{"id":"t139","label":"رحلتنا"},{"id":"t140","label":"ماذا نفعل"}]},{"id":"b143","kicker":"كيف يحدث التغيير","heading":"من صورة إلى عادة رعاية","items":[{"id":"s69","title":"انتبه","text":"تجعلنا السيلفي نتوقف وننظر حقًا إلى من ربّونا."},{"id":"s70","title":"اشكر","text":"سطر شكر واحد يقول ما نتركه كثيرًا دون قول."},{"id":"s71","title":"تصرّف","text":"يليها وعد: مكالمة أسبوعية، أو وجبة مشتركة، أو زيارة."},{"id":"s72","title":"ابقَ قريبًا","text":"الأفعال الصغيرة المتكرّرة تُبقي العائلات والمجتمعات متصلة."}]},{"id":"b144","kicker":"برامجنا","heading":"أربع طرق نرعى بها كبار السن","items":[{"id":"c85","title":"صحة كبار السن","text":"مخيمات فحص مجانية ودعم بالأدوية لكبار السن في المناطق الريفية.","bullets":[{"id":"i73","text":"فحوص ضغط الدم والسكر والعيون"},{"id":"i74","text":"المساعدة في المتابعة مع طبيب محلي"},{"id":"i75","text":"تذكيرات بالأدوية والمواعيد"}]},{"id":"c86","title":"الجسر بين الأجيال","text":"برامج مدرسية تُدخل الأجداد إلى الفصول لمشاركة مهاراتهم وحكاياتهم.","bullets":[{"id":"i76","text":"يوم الأجداد في المدارس والكليات"},{"id":"i77","text":"يسجّل الطلاب قصص العائلة ووصفاتها"},{"id":"i78","text":"تحدي السيلفي المدرسي السنوي"}]},{"id":"c87","title":"الحقوق والكرامة","text":"مساعدة كبار السن على فهم المعاشات وبرامج الرعاية والحماية من الإهمال.","bullets":[{"id":"i79","text":"أدلة مبسّطة للمعاشات والمزايا"},{"id":"i80","text":"المساعدة في الاستمارات والوثائق"},{"id":"i81","text":"توجيه العائلات إلى الخدمات القانونية وخدمات الدعم"}]},{"id":"c88","title":"الشمول الرقمي","text":"تعليم الآباء إجراء مكالمات الفيديو ودفع الفواتير والبقاء على تواصل مع العائلة البعيدة.","bullets":[{"id":"i82","text":"جلسات مساعدة على الهاتف يديرها متطوعون"},{"id":"i83","text":"اكتشاف الاحتيال الإلكتروني والمكالمات المزيّفة"},{"id":"i84","text":"مكالمات فيديو مع العائلة البعيدة"}]}]},{"id":"b145","kicker":"على هذا الموقع","heading":"طرق للمشاركة اليوم","items":[{"id":"c89","title":"شارك سيلفي","text":"انشر صورة مع والدك وسطر شكر واحدًا."},{"id":"c90","title":"زمان والآن","text":"ضع صورة قديمة بجانب صورة جديدة."},{"id":"c91","title":"جدار الذكريات","text":"تذكّر والدًا لم يعد بيننا."},{"id":"c92","title":"شجرة العائلة","text":"ابنِ شجرة عائلتك، سيلفي تلو الأخرى."},{"id":"c93","title":"تحدي المدارس","text":"أحضر الحملة إلى مدرستك أو كليتك."},{"id":"c94","title":"خذ التعهّد","text":"اختر وعدًا تحافظ عليه كل أسبوع."}]},{"id":"b146","kicker":"شارك معنا","heading":"هناك مكان للجميع","items":[{"id":"c95","title":"تطوّع","text":"اقضِ ساعة أسبوعيًا مع مسنّ يعيش وحده، أو ساعد في مخيم صحي قريب منك.","linkLabel":"تبنَّ جدًّا"},{"id":"c96","title":"كن شريكًا لنا","text":"يمكن للمدارس والمستشفيات والشركات والمجموعات المجتمعية تنفيذ الحملة معنا.","linkLabel":"راسلنا"},{"id":"c97","title":"انشر الخبر","text":"شارك الحملة مع مجموعة عائلتك أو مدرستك أو مكان عملك. كلما قال المزيد من الناس شكرًا، شعر مزيد من كبار السن بأنهم مرئيون."}]},{"id":"b147","title":"تبدأ بسيلفي واحدة","text":"التقطها اليوم، ولتكن بداية شيء يدوم.","buttons":[{"id":"b98","label":"شارك سيلفي"},{"id":"b99","label":"من نحن"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_what_we_do, 'es', N'Qué hacemos | Selfie with Parent', N'Campamentos de salud para mayores, programas escolares, ayuda con derechos y habilidades digitales, y visitas a quienes viven solos. Descubre cómo Selfie with Parent convierte la gratitud en cuidado.', N'[{"id":"b141","eyebrow":"Qué hacemos","title":"Gratitud que","highlight":"se convierte en cuidado","lead":"Todo empieza con el selfie. Aquí está todo lo que ocurre después."},{"id":"b142","items":[{"id":"t137","label":"Sobre nosotros"},{"id":"t138","label":"Nuestro fundador"},{"id":"t139","label":"Nuestro camino"},{"id":"t140","label":"Qué hacemos"}]},{"id":"b143","kicker":"Cómo ocurre el cambio","heading":"De una foto a un hábito de cuidado","items":[{"id":"s69","title":"Mirar","text":"Un selfie nos hace parar y mirar de verdad a quienes nos criaron."},{"id":"s70","title":"Agradecer","text":"Una frase de agradecimiento dice lo que tantas veces callamos."},{"id":"s71","title":"Actuar","text":"Después llega una promesa: una llamada semanal, una comida juntos, una visita."},{"id":"s72","title":"Seguir cerca","text":"Los pequeños gestos, repetidos, mantienen unidas a familias y comunidades."}]},{"id":"b144","kicker":"Nuestros programas","heading":"Cuatro formas de cuidar a los mayores","items":[{"id":"c85","title":"Salud de los mayores","text":"Revisiones gratuitas y ayuda con medicamentos para personas mayores en zonas rurales.","bullets":[{"id":"i73","text":"Controles de tensión, azúcar y vista"},{"id":"i74","text":"Ayuda para el seguimiento con un médico local"},{"id":"i75","text":"Recordatorios de medicinas y citas"}]},{"id":"c86","title":"Unir generaciones","text":"Programas escolares que llevan a los abuelos a las aulas para compartir saberes e historias.","bullets":[{"id":"i76","text":"Día de los abuelos en escuelas y universidades"},{"id":"i77","text":"Los estudiantes graban historias y recetas familiares"},{"id":"i78","text":"El reto anual de selfies escolar"}]},{"id":"c87","title":"Derechos y dignidad","text":"Ayudamos a los mayores a entender pensiones, ayudas sociales y la protección frente al abandono.","bullets":[{"id":"i79","text":"Guías sencillas sobre pensiones y ayudas"},{"id":"i80","text":"Ayuda con formularios y documentos"},{"id":"i81","text":"Orientar a las familias hacia servicios legales y de apoyo"}]},{"id":"c88","title":"Inclusión digital","text":"Enseñamos a los padres a hacer videollamadas, pagar facturas y mantenerse en contacto con la familia lejana.","bullets":[{"id":"i82","text":"Sesiones de ayuda con el móvil a cargo de voluntarios"},{"id":"i83","text":"Detectar estafas en línea y llamadas falsas"},{"id":"i84","text":"Videollamadas con la familia que vive lejos"}]}]},{"id":"b145","kicker":"En esta web","heading":"Formas de participar hoy","items":[{"id":"c89","title":"Comparte un selfie","text":"Publica una foto con tu padre o madre y una frase de agradecimiento."},{"id":"c90","title":"Antes y ahora","text":"Pon una foto antigua junto a una nueva."},{"id":"c91","title":"Muro de recuerdos","text":"Recuerda a un padre o una madre que ya no está."},{"id":"c92","title":"Árbol genealógico","text":"Construye tu árbol genealógico, selfie a selfie."},{"id":"c93","title":"Reto escolar","text":"Lleva la campaña a tu escuela o universidad."},{"id":"c94","title":"Haz el compromiso","text":"Elige una promesa que cumplir cada semana."}]},{"id":"b146","kicker":"Participa","heading":"Hay un lugar para todos","items":[{"id":"c95","title":"Hazte voluntario","text":"Pasa una hora a la semana con una persona mayor que vive sola, o ayuda en un campamento de salud cercano.","linkLabel":"Adopta un abuelo"},{"id":"c96","title":"Colabora con nosotros","text":"Escuelas, hospitales, empresas y grupos comunitarios pueden llevar la campaña con nosotros.","linkLabel":"Escríbenos"},{"id":"c97","title":"Corre la voz","text":"Comparte la campaña en el grupo de tu familia, tu escuela o tu trabajo. Cuantas más personas den las gracias, más mayores se sentirán vistos."}]},{"id":"b147","title":"Empieza con un selfie","text":"Hazlo hoy, y que sea el comienzo de algo duradero.","buttons":[{"id":"b98","label":"Comparte un selfie"},{"id":"b99","label":"Sobre nosotros"}]}]');
    INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson]) VALUES (@p_what_we_do, 'fr', N'Ce que nous faisons | Selfie with Parent', N'Camps de santé pour les seniors, programmes scolaires, aide aux droits et au numérique, et visites aux aînés seuls. Découvrez comment Selfie with Parent transforme la gratitude en attention.', N'[{"id":"b141","eyebrow":"Nos actions","title":"Une gratitude qui","highlight":"devient attention","lead":"Tout commence par le selfie. Voici tout ce qui se passe ensuite."},{"id":"b142","items":[{"id":"t137","label":"À propos"},{"id":"t138","label":"Notre fondateur"},{"id":"t139","label":"Notre parcours"},{"id":"t140","label":"Nos actions"}]},{"id":"b143","kicker":"Comment le changement se produit","heading":"D''une photo à une habitude d''attention","items":[{"id":"s69","title":"Remarquer","text":"Un selfie nous fait nous arrêter pour vraiment regarder ceux qui nous ont élevés."},{"id":"s70","title":"Remercier","text":"Une phrase de remerciement dit ce que nous taisons trop souvent."},{"id":"s71","title":"Agir","text":"Une promesse suit : un appel par semaine, un repas partagé, une visite."},{"id":"s72","title":"Rester proches","text":"De petits gestes répétés gardent familles et communautés liées."}]},{"id":"b144","kicker":"Nos programmes","heading":"Quatre façons de prendre soin des aînés","items":[{"id":"c85","title":"Santé des aînés","text":"Bilans gratuits et aide aux médicaments pour les seniors en zone rurale.","bullets":[{"id":"i73","text":"Contrôles de tension, glycémie et vue"},{"id":"i74","text":"Aide pour le suivi avec un médecin local"},{"id":"i75","text":"Rappels pour les médicaments et rendez-vous"}]},{"id":"c86","title":"Relier les générations","text":"Des programmes scolaires qui invitent les grands-parents en classe pour partager savoir-faire et histoires.","bullets":[{"id":"i76","text":"Journée des grands-parents dans les écoles"},{"id":"i77","text":"Les élèves enregistrent histoires et recettes de famille"},{"id":"i78","text":"Le défi selfie annuel des écoles"}]},{"id":"c87","title":"Droits et dignité","text":"Aider les aînés à comprendre retraites, aides sociales et protection contre la négligence.","bullets":[{"id":"i79","text":"Des guides simples sur les retraites et aides"},{"id":"i80","text":"Aide pour les formulaires et documents"},{"id":"i81","text":"Orienter les familles vers les services juridiques et d''aide"}]},{"id":"c88","title":"Inclusion numérique","text":"Apprendre aux parents à faire des appels vidéo, payer leurs factures et rester en lien avec la famille éloignée.","bullets":[{"id":"i82","text":"Ateliers téléphone animés par des bénévoles"},{"id":"i83","text":"Repérer les arnaques en ligne et faux appels"},{"id":"i84","text":"Des appels vidéo avec la famille éloignée"}]}]},{"id":"b145","kicker":"Sur ce site","heading":"Comment participer dès aujourd''hui","items":[{"id":"c89","title":"Partager un selfie","text":"Publiez une photo avec votre parent et une phrase de remerciement."},{"id":"c90","title":"Avant et maintenant","text":"Mettez une ancienne photo à côté d''une nouvelle."},{"id":"c91","title":"Mur des souvenirs","text":"Rendez hommage à un parent disparu."},{"id":"c92","title":"Arbre généalogique","text":"Construisez votre arbre généalogique, un selfie à la fois."},{"id":"c93","title":"Défi des écoles","text":"Amenez la campagne dans votre école ou université."},{"id":"c94","title":"Prendre l''engagement","text":"Choisissez une promesse à tenir chaque semaine."}]},{"id":"b146","kicker":"S''impliquer","heading":"Il y a une place pour chacun","items":[{"id":"c95","title":"Devenir bénévole","text":"Passez une heure par semaine avec un aîné qui vit seul, ou aidez dans un camp de santé près de chez vous.","linkLabel":"Adoptez un grand-parent"},{"id":"c96","title":"Devenir partenaire","text":"Écoles, hôpitaux, entreprises et associations peuvent mener la campagne avec nous.","linkLabel":"Écrivez-nous"},{"id":"c97","title":"Faites passer le mot","text":"Partagez la campagne avec votre groupe familial, votre école ou votre travail. Plus il y a de mercis, plus les aînés se sentent vus."}]},{"id":"b147","title":"Tout commence par un selfie","text":"Prenez-le aujourd''hui, et que ce soit le début de quelque chose qui dure.","buttons":[{"id":"b98","label":"Partager un selfie"},{"id":"b99","label":"À propos"}]}]');
END
